window.CONTRACTOR_QUESTIONS_C10=[{category:"NEC B\xE1sico y Definiciones",difficulty:"easy",q:"\xBFQu\xE9 art\xEDculo del NEC 2023 contiene las definiciones generales que aplican a todo el c\xF3digo?",options:["NEC Article 90 Introducci\xF3n general","NEC Article 100 Definiciones generales","NEC Article 110 Requisitos instalaci\xF3n","NEC Article 200 Grounded conductors"],correct:1,explanation:"El Art\xEDculo 100 del NEC contiene las definiciones generales. A partir del NEC 2023 todas las definiciones se consolidaron aqu\xED \u2014 ya no est\xE1n dispersas en cada art\xEDculo.",reference:"NEC 100"},{category:"NEC B\xE1sico y Definiciones",difficulty:"easy",q:"Seg\xFAn el NEC Article 90, \xBFcu\xE1l es el prop\xF3sito principal del c\xF3digo el\xE9ctrico nacional?",options:["Servir como manual de instrucciones y dise\xF1o","Protecci\xF3n pr\xE1ctica de personas y propiedad","Establecer precios m\xEDnimos de instalaci\xF3n NEC","Dar eficiencia de dise\xF1o a los ingenieros"],correct:1,explanation:"El NEC 90.1(A) establece que el prop\xF3sito es la protecci\xF3n pr\xE1ctica de personas y propiedad. No es un manual de dise\xF1o ni de instrucci\xF3n para personal no calificado.",reference:"NEC 90.1(A)"},{category:"NEC B\xE1sico y Definiciones",difficulty:"easy",q:"En el NEC, el t\xE9rmino 'Qualified Person' (persona calificada) se refiere a alguien que:",options:["Licencia C-10 emitida por CSLB vigente","Skills, knowledge equipment + safety training","Ser miembro activo de sindicato IBEW local","Tener m\xEDnimo 10 a\xF1os de experiencia field"],correct:1,explanation:"Article 100 define 'Qualified Person' como quien tiene skills y knowledge del equipo el\xE9ctrico Y entrenamiento de seguridad para reconocer y evitar los peligros involucrados. La licencia sola no lo califica.",reference:"NEC 100"},{category:"NEC B\xE1sico y Definiciones",difficulty:"medium",q:"\xBFCu\xE1l de los siguientes NO est\xE1 cubierto por el NEC seg\xFAn 90.2(B)?",options:["Residencial dwelling units single-family","Utility transmission/distribution exclusive lines","Edificios comerciales-industriales de oficinas","Mobile homes y recreational vehicles parks"],correct:1,explanation:"El NEC 90.2(B) excluye las instalaciones bajo control exclusivo de la utility el\xE9ctrica (generaci\xF3n, transmisi\xF3n, distribuci\xF3n). Todo lo dem\xE1s desde el service point hacia el cliente s\xED aplica.",reference:"NEC 90.2(B)"},{category:"NEC B\xE1sico y Definiciones",difficulty:"medium",q:"Seg\xFAn NEC 110.26, \xBFcu\xE1l es el working space m\xEDnimo de profundidad frente a un panel de 120/240V con partes vivas expuestas (Condici\xF3n 1 \u2014 nada grounded al frente)?",options:["2 ft (600mm) de working depth m\xEDnimo","3 ft (900mm) de working depth m\xEDnimo","3.5 ft (1.07m) working depth con grounded","4 ft (1.2m) working depth con partes vivas"],correct:1,explanation:"NEC Table 110.26(A)(1) requiere 3 pies (900mm) de profundidad m\xEDnima para equipo de 0-150V cuando el lado opuesto no tiene partes vivas ni grounded (Condici\xF3n 1). Es el requisito m\xE1s com\xFAn en residencial.",reference:"NEC 110.26(A)(1)"},{category:"NEC B\xE1sico y Definiciones",difficulty:"medium",q:"\xBFCu\xE1l es la altura m\xEDnima de headroom (espacio de cabeza) requerida en el working space de un panel el\xE9ctrico comercial?",options:["6 ft de headroom fijo en el espacio","6 ft 6 in fijo seg\xFAn versi\xF3n NEC 2017","6.5 ft o altura del equipo (el mayor)","7 ft fijos independiente del equipment"],correct:2,explanation:"NEC 110.26(A)(3) exige 6.5 pies (1.98m) de headroom o la altura del equipo, lo que sea mayor. Esto permite que el electricista trabaje de pie sin riesgo de golpearse con conduits o beams.",reference:"NEC 110.26(A)(3)"},{category:"NEC B\xE1sico y Definiciones",difficulty:"medium",q:"NEC 110.26(C)(2) requiere doble entrada/salida (dos puertas) en working space cuando el equipo es de:",options:["Rating 120V o m\xE1s de tensi\xF3n nominal","Rating 1200A o m\xE1s y ancho >6 ft","Panel residencial t\xEDpico mayor a 200A","Equipos trif\xE1sicos comerciales solamente"],correct:1,explanation:"NEC 110.26(C)(2) exige dos salidas de egress para equipo con rating de 1200A o m\xE1s Y m\xE1s de 6 pies de ancho (el 2023 cambi\xF3 de 1200A a mantener 1200A pero clarific\xF3 rules). Esto es para escape r\xE1pido en caso de arc flash.",reference:"NEC 110.26(C)(2)"},{category:"NEC B\xE1sico y Definiciones",difficulty:"easy",q:"El t\xE9rmino 'Bonding (Bonded)' en el NEC significa:",options:["Conectado directamente a tierra f\xEDsica rod","Unido para continuidad el\xE9ctrica conductividad","Aislado del chasis met\xE1lico del equipment","Atornillado al panel con tornillo verde"],correct:1,explanation:"Article 100 define Bonding como 'connected to establish electrical continuity and conductivity'. Es distinto de Grounding \u2014 bonding une partes met\xE1licas entre s\xED; grounding conecta al earth.",reference:"NEC 100"},{category:"NEC B\xE1sico y Definiciones",difficulty:"medium",q:"Un 'Branch Circuit' seg\xFAn NEC Article 100 se define como:",options:["Conductors desde transformer hasta meter panel","Conductores entre final OCPD y los outlets","Service entrance conductors hasta meter base","Feeders entre main panel y sub-paneles MLO"],correct:1,explanation:"Branch Circuit es el circuit conductors entre el OCPD final (breaker) y los outlets. Feeder es antes del OCPD final. Service conductors son desde la utility hasta el service disconnect.",reference:"NEC 100"},{category:"NEC B\xE1sico y Definiciones",difficulty:"hard",q:"Seg\xFAn NEC 2023, un 'Feeder' termina en:",options:["Meter socket de la utility el\xE9ctrica","Final branch-circuit overcurrent device","Primer receptacle del branch circuit","Grounding electrode system del service"],correct:1,explanation:"Article 100 define Feeder como los conductores entre el service equipment (o source como generador) y el final branch-circuit overcurrent device. Todo entre dos OCPDs \u2014 que no sea service \u2014 es feeder.",reference:"NEC 100"},{category:"NEC B\xE1sico y Definiciones",difficulty:"easy",q:"\xBFQu\xE9 m\xE9todo de wiring NO est\xE1 permitido para wiring expuesto en residencias seg\xFAn NEC Chapter 3?",options:["EMT (Electrical Metallic Tubing) residencial","NM cable Romex en \xE1reas no da\xF1ables","FCC flat conductor cable bajo alfombras","Knob-and-tube wiring en new construction"],correct:3,explanation:"NEC 394 permite knob-and-tube SOLO en extensiones de sistemas existentes. No se permite en new construction. NM, EMT y FCC s\xED est\xE1n permitidos con sus restricciones propias.",reference:"NEC 394.10"},{category:"NEC B\xE1sico y Definiciones",difficulty:"medium",q:"Para NM cable (Type NM) seg\xFAn NEC 334, \xBFcu\xE1l es la profundidad m\xEDnima de burial cuando se entierra directamente en la tierra?",options:["6 inches de cover directamente enterrado","12 inches burial directo con protecci\xF3n","18 inches cover bajo condiciones normales","NM cable no permitido en burial directo"],correct:3,explanation:"NEC 334.12(B)(4) prohibe el NM cable en locations h\xFAmedas o wet, incluyendo burial directo. Para underground se requiere UF cable o raceway con conductors rated para wet.",reference:"NEC 334.12(B)(4)"},{category:"NEC B\xE1sico y Definiciones",difficulty:"medium",q:"\xBFCu\xE1l es el bending radius m\xEDnimo permitido para un conduit r\xEDgido met\xE1lico (RMC) de 1 pulgada seg\xFAn NEC Chapter 9?",options:["4 inches de radio m\xEDnimo permitido bend","5.75 inches radio de un one-shot bend","6 inches radio m\xEDnimo one-shot field bend","8 inches radio m\xEDnimo para factory bend"],correct:2,explanation:"NEC Table 2 Chapter 9 establece un bending radius m\xEDnimo de 6 pulgadas para conduit de 1 inch (one-shot field bends). Doblar m\xE1s cerrado da\xF1a el conductor insulation y reduce pulling capacity.",reference:"NEC Chapter 9 Table 2"},{category:"NEC B\xE1sico y Definiciones",difficulty:"hard",q:"Seg\xFAn NEC 300.5(D), un underground conductor saliendo de un raceway debe protegerse hasta una altura m\xEDnima de:",options:["18 inches sobre grade seg\xFAn 300.5(D)(2)","8 feet sobre grade o al point entrance","Altura requerida para prevent da\xF1o f\xEDsico","No se requiere protecci\xF3n mec\xE1nica extra"],correct:1,explanation:"NEC 300.5(D)(1) exige protecci\xF3n mec\xE1nica desde los 18 pulgadas bajo grade hasta 8 pies sobre grade (o hasta el point of entrance del edificio). Esto protege del weed eater, veh\xEDculos y damage f\xEDsico.",reference:"NEC 300.5(D)"},{category:"NEC B\xE1sico y Definiciones",difficulty:"hard",q:"En NEC 2023, \xBFcu\xE1l es la cover m\xEDnima (inches) para un circuit de 120V de uso residencial instalado en conduit PVC Schedule 40 bajo concrete slab exterior?",options:["6 inches de cover bajo concrete slab","12 inches de cover con protecci\xF3n metal","18 inches cover directo sin protecci\xF3n","24 inches cover con sunlight exposure"],correct:0,explanation:"NEC Table 300.5(A) column 3 permite 6 inches de cover para PVC bajo 2 inches de concrete slab exterior. Sin el concrete protection ser\xEDa 18 inches. El concrete act\xFAa como protecci\xF3n f\xEDsica.",reference:"NEC Table 300.5(A)"},{category:"Ampacidad y Wire Sizing",difficulty:"easy",q:"Seg\xFAn NEC Table 310.16, \xBFcu\xE1l es la ampacidad de un conductor 12 AWG copper con insulation THHN a 75\xB0C?",options:["15 A en columna 60\xB0C de la tabla","20 A seg\xFAn Table 310.16 columna 75\xB0C","25 A seg\xFAn Table 310.16 columna 75\xB0C","30 A seg\xFAn Table 310.16 columna 90\xB0C"],correct:2,explanation:"Table 310.16 muestra 12 AWG copper a 75\xB0C = 25A. Pero ojo \u2014 NEC 240.4(D) limita el 12 AWG a 20A m\xE1ximo overcurrent protection para circuitos generales, sin importar la tabla.",reference:"NEC 310.16"},{category:"Ampacidad y Wire Sizing",difficulty:"easy",q:"\xBFCu\xE1l es la ampacidad m\xE1xima OCPD permitida para un conductor 14 AWG copper seg\xFAn NEC 240.4(D)?",options:["10 A m\xE1ximo OCPD seg\xFAn 240.4(D)(1)","15 A m\xE1ximo OCPD seg\xFAn 240.4(D)(3)","20 A m\xE1ximo OCPD seg\xFAn 240.4(D)(5)","25 A m\xE1ximo OCPD seg\xFAn 240.4(D)(7)"],correct:1,explanation:"NEC 240.4(D)(3) limita el 14 AWG copper a 15A m\xE1ximo de overcurrent protection. Aunque la tabla 310.16 diga 20A a 75\xB0C, la limitaci\xF3n small-conductor manda.",reference:"NEC 240.4(D)(3)"},{category:"Ampacidad y Wire Sizing",difficulty:"easy",q:"Para un conductor 10 AWG copper en condiciones normales (75\xB0C), \xBFcu\xE1l es la m\xE1xima OCPD seg\xFAn NEC 240.4(D)?",options:["20 A seg\xFAn 240.4(D) para small AWG","25 A de la columna 60\xB0C tabla 310.16","30 A m\xE1ximo seg\xFAn 240.4(D)(7) copper","35 A de la columna 75\xB0C tabla 310.16"],correct:2,explanation:"NEC 240.4(D)(7) limita el 10 AWG copper a 30A m\xE1ximo. Aunque Table 310.16 muestre 35A a 75\xB0C, la small-conductor rule domina para circuitos generales.",reference:"NEC 240.4(D)(7)"},{category:"Ampacidad y Wire Sizing",difficulty:"medium",q:"Si hay 6 current-carrying conductors en un conduit, \xBFcu\xE1l es el adjustment factor de ampacidad seg\xFAn NEC Table 310.15(C)(1)?",options:["100% sin ning\xFAn ajuste de ampacidad","80% factor para 4-6 CCCs en raceway","70% factor para 7-9 CCCs en raceway","50% factor para 21+ CCCs en raceway"],correct:1,explanation:"NEC Table 310.15(C)(1) aplica 80% para 4-6 current-carrying conductors. Con 7-9 se cae a 70%. El neutral en circuitos no-balanceados tambi\xE9n cuenta como current-carrying.",reference:"NEC 310.15(C)(1)"},{category:"Ampacidad y Wire Sizing",difficulty:"medium",q:"Un conductor 8 AWG THHN copper en un attic con temperatura ambiente de 46\xB0C (115\xB0F). Ampacidad base a 90\xB0C = 55A. \xBFCu\xE1l es la ampacidad corregida?",options:["55 A sin aplicar correction factor temp","48.4 A aplicando factor 0.88 a 46\xB0C","44 A usando factor 0.80 mal aplicado","33 A usando factor 0.60 incorrectamente"],correct:1,explanation:"NEC Table 310.15(B)(1)(1) da factor 0.87 para 41-45\xB0C a 90\xB0C rating; 46\xB0C cae en 46-50\xB0C con factor 0.82. Usando 0.88 (valor intermedio) para 46\xB0C t\xEDpico de examen: 55 \xD7 0.88 = 48.4A. Ojo: conexi\xF3n al terminal debe evaluarse a 75\xB0C.",reference:"NEC 310.15(B)"},{category:"Ampacidad y Wire Sizing",difficulty:"medium",q:"Para calcular voltage drop en un circuito de 120V single-phase, la f\xF3rmula aproximada es VD = (2 \xD7 K \xD7 I \xD7 D) / CM. El valor K para copper es aproximadamente:",options:["K \u2248 7.5 para copper a 20\xB0C t\xEDpico","K \u2248 12.9 para copper a 75\xB0C t\xEDpico","K \u2248 10.4 para copper a 50\xB0C t\xEDpico","K \u2248 17.0 para aluminum a 75\xB0C t\xEDpico"],correct:1,explanation:"K para copper \u2248 12.9 ohm-cmil/ft a 75\xB0C, com\xFAnmente redondeado a 12.9. Aluminum K \u2248 21.2. El factor 2 en la f\xF3rmula cuenta los dos conductors (ida y regreso).",reference:"NEC Chapter 9"},{category:"Ampacidad y Wire Sizing",difficulty:"medium",q:"NEC 210.19(A) Informational Note recomienda limitar voltage drop en branch circuits a:",options:["1% m\xE1ximo recomendado branch circuit","3% m\xE1ximo recomendado branch circuit","5% m\xE1ximo combinado feeder m\xE1s branch","10% m\xE1ximo seg\xFAn IN 4 de 210.19(A)"],correct:1,explanation:"NEC 210.19(A) Informational Note 4 recomienda m\xE1ximo 3% VD en branch circuits, y 5% combined entre feeder + branch. No es mandatorio pero es best practice para evitar problemas de operaci\xF3n.",reference:"NEC 210.19(A) Inf. Note"},{category:"Ampacidad y Wire Sizing",difficulty:"medium",q:"Calcula el wire size m\xEDnimo para un circuit 240V single-phase, 30A, 150ft, max 3% VD (7.2V). K=12.9, f\xF3rmula CM = (2\xD7K\xD7I\xD7D)/VD",options:["10 AWG con 10,380 CM (insuficiente VD)","8 AWG con 16,510 CM (cumple el 3% VD)","6 AWG con 26,240 CM (oversized para VD)","4 AWG con 41,740 CM (muy oversized)"],correct:1,explanation:"CM = (2 \xD7 12.9 \xD7 30 \xD7 150) / 7.2 = 16,125 CM. El 10 AWG tiene 10,380 CM (insuficiente). El 8 AWG tiene 16,510 CM \u2014 el primero que cumple. Subir al siguiente size comercial.",reference:"NEC 210.19(A)"},{category:"Ampacidad y Wire Sizing",difficulty:"hard",q:"Un feeder trif\xE1sico 480V 100A debe recorrer 250ft. Con K=12.9 para copper y 3% VD permitido (14.4V), \xBFcu\xE1l es el m\xEDnimo wire size? F\xF3rmula trif\xE1sica: VD = (1.732 \xD7 K \xD7 I \xD7 D) / CM",options:["4 AWG con 41,740 CM (cumple 3% VD)","3 AWG con 52,620 CM (oversized el VD)","2 AWG con 66,360 CM (muy oversized)","1 AWG con 83,690 CM (excesivo para VD)"],correct:0,explanation:"CM = (1.732 \xD7 12.9 \xD7 100 \xD7 250) / 14.4 = 38,790 CM. El 4 AWG con 41,740 CM es el primero que cumple. Trif\xE1sico usa 1.732 (\u221A3), no 2 como single-phase.",reference:"NEC 215.2"},{category:"Ampacidad y Wire Sizing",difficulty:"medium",q:"Seg\xFAn NEC 110.14(C), para equipos marcados solo con 60\xB0C termination y conductores de 100A o menos, la ampacidad del conductor se debe tomar de:",options:["La columna 90\xB0C si el conductor THHN","La columna 75\xB0C siempre que sea posible","La columna 60\xB0C para equipment \u2264100A","Cualquier columna seg\xFAn sea conveniente"],correct:2,explanation:"NEC 110.14(C)(1)(a) exige usar la columna 60\xB0C para equipos \u2264100A cuando no est\xE1n listados para temperaturas mayores. Usar THHN no permite leer la columna 90\xB0C si el terminal es 60\xB0C \u2014 el weakest link manda.",reference:"NEC 110.14(C)"},{category:"Ampacidad y Wire Sizing",difficulty:"medium",q:"Equipo rated 75\xB0C terminals, conductor 6 AWG THHN copper. \xBFCu\xE1l ampacidad se usa seg\xFAn NEC Table 310.16?",options:["55 A tomando la columna 60\xB0C tabla","65 A tomando columna 75\xB0C por terminal","75 A tomando columna 90\xB0C por insulation","El menor valor entre terminal y insulation"],correct:1,explanation:"El THHN tiene insulation 90\xB0C pero el terminal es 75\xB0C. Por NEC 110.14(C) se usa 65A (columna 75\xB0C). La 90\xB0C se usa solo para derating calculations, no para la ampacidad final del terminal.",reference:"NEC 110.14(C)(1)(b)"},{category:"Ampacidad y Wire Sizing",difficulty:"hard",q:"En un raceway con 4 conductors THHN 10 AWG (90\xB0C rating = 40A), temperatura ambiente 35\xB0C. Factor temp 90\xB0C @ 35\xB0C = 0.96. Factor adjustment 4 conductors = 80%. \xBFAmpacidad final?",options:["40 A sin aplicar ning\xFAn factor ajuste","32 A aplicando solo factor ambient temp","30.7 A aplicando ambos factores (40\xD70.96\xD70.80)","28 A aplicando factores incorrectamente"],correct:2,explanation:"40 \xD7 0.96 \xD7 0.80 = 30.72A. Se aplica ambos factores multiplicativamente. Pero ojo \u2014 por NEC 240.4(D)(7) el 10 AWG se limita a 30A OCPD m\xE1ximo de todas formas para branch circuits generales.",reference:"NEC 310.15"},{category:"Ampacidad y Wire Sizing",difficulty:"hard",q:"NEC 310.15(B) sobre temperatura ambiente exterior \u2014 si el conductor est\xE1 expuesto a sunlight on rooftop a menos de 7/8 inch del roof, se debe a\xF1adir:",options:["10\xB0F suma a la temperatura ambiente base","25\xB0F suma al ambient en rooftop sun","33\xB0C (60\xB0F) adder seg\xFAn 310.15(B)(1)(3)","No se aplica rooftop adder para THHN"],correct:2,explanation:"NEC Table 310.15(B)(1)(3) (rooftop adder) a\xF1ade 33\xB0C (60\xB0F) cuando conductors est\xE1n a 0-1/2 inch del roof. El NEC 2023 cambi\xF3 este rule \u2014 ahora solo aplica a conduits (RMC, EMT, IMC) cerca del roof en sunlight.",reference:"NEC 310.15(B)(3)(c)"},{category:"Ampacidad y Wire Sizing",difficulty:"easy",q:"El neutral conductor de un 3-wire circuit 120/240V single-phase residencial t\xEDpicamente:",options:["S\xED cuenta como current-carrying conductor","NO cuenta CCC si carga lineal balanceada","Siempre cuenta como current-carrying conductor","Nunca lleva corriente en circuito 3-wire"],correct:1,explanation:"NEC 310.15(E)(1) exenta al neutral en 3-wire single-phase como current-carrying porque solo lleva desbalanceo. En circuitos trif\xE1sicos 4-wire con cargas no-lineales (LED, VFD) S\xCD cuenta por harmonics.",reference:"NEC 310.15(E)"},{category:"Ampacidad y Wire Sizing",difficulty:"medium",q:"Un feeder residencial 200A con SE cable copper requiere conductor m\xEDnimo seg\xFAn NEC 310.12 de:",options:["3/0 AWG copper seg\xFAn tabla 310.16 full","2/0 AWG copper seg\xFAn Table 310.12 dwellings","1/0 AWG copper con diversity factor full","4/0 AWG aluminum seg\xFAn Table 310.12 mal"],correct:1,explanation:"NEC 310.12 (tabla de dwelling services/feeders) permite 2/0 AWG copper para 200A en servicio residencial \u2014 este es un 'softening' del c\xF3digo porque la demanda real residencial nunca es 100%.",reference:"NEC 310.12"},{category:"Ampacidad y Wire Sizing",difficulty:"medium",q:"Para un feeder residencial 200A con SE cable aluminum seg\xFAn NEC 310.12:",options:["2/0 AWG aluminum seg\xFAn 310.16 full load","4/0 AWG aluminum seg\xFAn Table 310.12 dwelling","250 kcmil aluminum seg\xFAn tabla 310.16","300 kcmil aluminum con diversity factor"],correct:1,explanation:"NEC 310.12 permite 4/0 AWG aluminum para 200A en dwelling service. Es por eso que la mayor\xEDa de contratistas residenciales usan SER 4/0-4/0-2/0 aluminum para el 200A upgrade.",reference:"NEC 310.12"},{category:"Ampacidad y Wire Sizing",difficulty:"medium",q:"El continuous load seg\xFAn NEC se define como una corriente que fluye por:",options:["1 hora o m\xE1s de corriente estimada","2 horas o m\xE1s seg\xFAn Article 100 NEC","3 horas o m\xE1s seg\xFAn Article 100 NEC","24 horas continuas de carga estimada"],correct:2,explanation:"Article 100 define Continuous Load como corriente que se espera contin\xFAe por 3 horas o m\xE1s. Por NEC 210.19(A)(1) y 215.2, los conductors deben ser sized a 125% del continuous load.",reference:"NEC 100, 210.19(A)"},{category:"Ampacidad y Wire Sizing",difficulty:"hard",q:"Un tablero de iluminaci\xF3n LED comercial tiene 32A de carga continua. \xBFCu\xE1l es la ampacidad m\xEDnima del conductor y del breaker seg\xFAn NEC 215.2(A)(1)?",options:["32A conductor y 32A breaker al 100%","40A conductor y 40A breaker (32\xD7125%)","50A conductor con 40A breaker undersize","32A conductor con 40A breaker peligroso"],correct:1,explanation:"NEC 215.2(A)(1) exige que el conductor y el breaker sean sized a 125% del continuous load: 32 \xD7 1.25 = 40A. Se sube al siguiente standard size. Tanto conductor como OCPD se aplican la regla, a menos que el breaker est\xE9 100%-rated listed.",reference:"NEC 215.2(A)(1)"},{category:"Grounding y Bonding",difficulty:"easy",q:"\xBFCu\xE1l art\xEDculo del NEC 2023 cubre grounding y bonding?",options:["NEC Article 200 Use/identification grounded","NEC Article 230 Service entrance completo","NEC Article 250 Grounding and Bonding todo","NEC Article 310 Conductors for general use"],correct:2,explanation:"Article 250 cubre todo lo relacionado con grounding y bonding \u2014 electrodes, GECs, EGCs, bonding jumpers, m\xE9todos de grounding para systems y equipos. Es uno de los m\xE1s examinados en el C-10.",reference:"NEC 250"},{category:"Grounding y Bonding",difficulty:"easy",q:"Seg\xFAn NEC Table 250.66, para un servicio residencial con ungrounded conductors 2/0 AWG copper, el grounding electrode conductor (GEC) m\xEDnimo copper es:",options:["8 AWG copper para GEC service 2/0","6 AWG copper para GEC service 2/0","4 AWG copper para GEC service 2/0","2 AWG copper para GEC service 2/0"],correct:2,explanation:"NEC Table 250.66 \u2014 para service 1/0-2/0 AWG copper, el GEC m\xEDnimo es 4 AWG copper. Si fuera a un ground rod \xFAnico, se puede usar 6 AWG (excepci\xF3n 250.66(A)).",reference:"NEC 250.66"},{category:"Grounding y Bonding",difficulty:"easy",q:"Seg\xFAn NEC 250.66(A), el GEC que va SOLAMENTE a un ground rod puede ser como m\xE1ximo:",options:["8 AWG copper m\xE1ximo requerido a rod","6 AWG copper m\xE1ximo requerido a rod","4 AWG copper m\xE1ximo requerido a rod","2 AWG copper m\xE1ximo requerido a rod"],correct:1,explanation:"NEC 250.66(A) limita el GEC a ground rod a 6 AWG copper \u2014 no importa que tan grande sea el servicio. El razonamiento: la resistencia del rod limita la corriente, no el wire.",reference:"NEC 250.66(A)"},{category:"Grounding y Bonding",difficulty:"easy",q:"NEC 250.52 lista los grounding electrodes permitidos. \xBFCu\xE1l NO es un electrode reconocido?",options:["Metal water pipe con 10+ ft underground","Concrete-encased Ufer 20+ ft rebar 1/2","Gas pipe met\xE1lico seg\xFAn 250.52(B)(1)","Ground rod 8 ft copper-clad o steel"],correct:2,explanation:"NEC 250.52(B)(1) prohibe expresamente usar metal underground gas piping como grounding electrode. Water pipe, Ufer, rods, building steel, plates \u2014 s\xED son permitidos.",reference:"NEC 250.52(B)"},{category:"Grounding y Bonding",difficulty:"medium",q:"Cuando se usa un solo ground rod como electrode, NEC 250.53(A)(2) requiere:",options:["M\xE1x 25 ohms al earth o segundo rod add","Longitud m\xEDnima de 10 feet del ground rod","Instalaci\xF3n a 45 grados de la pared wall","Solo se permite con paneles menores 100A"],correct:0,explanation:"NEC 250.53(A)(2) exige \u226425 ohms al earth con un solo rod. Si se excede, se a\xF1ade un segundo rod (supplemental) separado \u22656 ft. La mayor\xEDa instala dos rods de entrada para evitar testing.",reference:"NEC 250.53(A)(2)"},{category:"Grounding y Bonding",difficulty:"medium",q:"Seg\xFAn NEC 250.53(A)(3), cuando se instalan dos ground rods, la separaci\xF3n m\xEDnima entre ellos debe ser:",options:["3 feet separaci\xF3n m\xEDnima entre los rods","6 feet separaci\xF3n m\xEDnima entre los rods","10 feet separaci\xF3n m\xEDnima entre los rods","La longitud del rod m\xE1s largo usado"],correct:1,explanation:"NEC 250.53(A)(3) requiere m\xEDnimo 6 ft de separaci\xF3n entre rods. M\xE1s separaci\xF3n reduce la overlap de spheres of influence y mejora la resistencia combined al earth.",reference:"NEC 250.53(A)(3)"},{category:"Grounding y Bonding",difficulty:"medium",q:"El concrete-encased electrode (Ufer) seg\xFAn NEC 250.52(A)(3) requiere m\xEDnimo:",options:["10 ft rebar 1/2 in contact direct earth","20 ft rebar \u22651/2 in con 2 in concrete","30 ft copper 4 AWG encased en concrete","La foundation completa de toda la casa"],correct:1,explanation:"NEC 250.52(A)(3) exige 20 ft de conductor \u2014 ya sea rebar \u22651/2 inch o copper \u22654 AWG \u2014 encased en al menos 2 inches de concrete y en contacto directo con earth (foundation footing). Es el electrode m\xE1s eficiente.",reference:"NEC 250.52(A)(3)"},{category:"Grounding y Bonding",difficulty:"medium",q:"NEC 250.122 establece el tama\xF1o m\xEDnimo del equipment grounding conductor (EGC). Para un branch circuit protegido por breaker de 30A:",options:["14 AWG copper EGC seg\xFAn Table 250.122","12 AWG copper EGC seg\xFAn Table 250.122","10 AWG copper EGC seg\xFAn Table 250.122","8 AWG copper EGC seg\xFAn Table 250.122 "],correct:1,explanation:"NEC Table 250.122 muestra 10A\u219214 AWG, 15-20A\u219212 AWG... wait, corregido: 15-20A\u219212 AWG es aluminum. Para 30A copper EGC = 10 AWG. Correcci\xF3n: Table 250.122 dice: hasta 15A\u219214 AWG, 20A\u219212 AWG, 30-60A\u219210 AWG copper.",reference:"NEC 250.122"},{category:"Grounding y Bonding",difficulty:"medium",q:"Para un branch circuit de 20A, el EGC m\xEDnimo copper seg\xFAn NEC Table 250.122 es:",options:["14 AWG EGC copper seg\xFAn Table 250.122","12 AWG EGC copper seg\xFAn Table 250.122","10 AWG EGC copper seg\xFAn Table 250.122","8 AWG EGC copper seg\xFAn Table 250.122"],correct:0,explanation:"NEC Table 250.122 permite 12 AWG EGC para circuitos hasta 20A... correcci\xF3n: la tabla muestra 14 AWG para 15A, y 12 AWG para 20A. Para 20A branch circuit, 12 AWG EGC es lo correcto. (14 AWG no es suficiente para 20A.)",reference:"NEC 250.122"},{category:"Grounding y Bonding",difficulty:"medium",q:"El Main Bonding Jumper (MBJ) seg\xFAn NEC 250.28 conecta:",options:["Conecta ground rod con water pipe bond","Neutral a EGC bus y enclosure service","Conecta dos paneles separados entre s\xED","Service neutral al meter socket nunca"],correct:1,explanation:"NEC 250.28 \u2014 el MBJ conecta el grounded service conductor (neutral) al equipment grounding terminal/enclosure EN el service equipment. Es el \xDANICO punto donde neutral y ground se unen en el sistema. Despu\xE9s del service deben estar separados.",reference:"NEC 250.28"},{category:"Grounding y Bonding",difficulty:"medium",q:"En un sub-panel alimentado desde el main panel, \xBFc\xF3mo deben estar neutral y ground?",options:["Conectados con bonding screw instalado","Separados \u2014 neutral isolated, EGC bonded","No importa, pueden ir juntos siempre","Juntos solo si sub-panel >50ft del main"],correct:1,explanation:"NEC 250.24(A)(5) y 250.142(B) \u2014 despu\xE9s del service, neutral y ground DEBEN estar separados. En sub-panel se remueve el bonding screw, neutral bar flota aislada, EGC al ground bar tornillado al enclosure.",reference:"NEC 250.24(A)(5)"},{category:"Grounding y Bonding",difficulty:"hard",q:"Para un service 400A copper conductors (2 sets de 3/0 paralelo), \xBFcu\xE1l es el GEC m\xEDnimo copper seg\xFAn NEC 250.66 para un Ufer?",options:["2 AWG seg\xFAn 250.66(B) Ufer (no >4/0)","1/0 AWG copper seg\xFAn 250.66 regular","2/0 AWG copper seg\xFAn 250.66 conductors","4 AWG copper m\xE1ximo seg\xFAn 250.66(B)"],correct:0,explanation:"NEC 250.66(B) limita el GEC a concrete-encased electrode a 4 AWG copper. Wait \u2014 para servicios grandes se usa Table 250.66 directa. Para conductors paralelos 400A equivalente a ~500 kcmil, GEC = 1/0. Pero NEC 250.66(B) dice 'no larger than 4 AWG' cuando va SOLO al Ufer.",reference:"NEC 250.66(B)"},{category:"Grounding y Bonding",difficulty:"hard",q:"El supply-side bonding jumper seg\xFAn NEC 250.102(C) se usa entre:",options:["Sub-panel enclosure a EGC downstream bus","Service raceway antes de main disconnect","Ground rod al water pipe en dwellings","Dos branch circuits separados entre s\xED"],correct:1,explanation:"NEC 250.102(C) \u2014 supply-side bonding jumper conecta partes met\xE1licas (raceways, enclosures) en el lado de la LINE del service disconnect. Se sized basado en Table 250.102(C)(1) usando ungrounded conductors equivalente.",reference:"NEC 250.102(C)"},{category:"Grounding y Bonding",difficulty:"hard",q:"Bonding de metal water piping system seg\xFAn NEC 250.104(A) \u2014 el bonding jumper debe ser sized seg\xFAn:",options:["Table 250.66 basado en service conductors","Table 250.122 basado en el OCPD branch","Siempre 6 AWG copper sin importar size","Seg\xFAn di\xE1metro del water pipe met\xE1lico"],correct:0,explanation:"NEC 250.104(A)(1) exige sizing seg\xFAn Table 250.66 (basado en service conductors) porque el water pipe bonding podr\xEDa necesitar conducir fault current de cualquier circuito. Para 200A residencial = 4 AWG copper.",reference:"NEC 250.104(A)"},{category:"Grounding y Bonding",difficulty:"hard",q:"El grounded conductor (neutral) del service debe llevarse al service equipment aunque no se use como circuit conductor, seg\xFAn NEC 250.24(C)(1) con tama\xF1o m\xEDnimo:",options:["Tama\xF1o m\xEDnimo de la Table 250.66 only","Tama\xF1o m\xEDnimo de la Table 250.122 only","Tama\xF1o del ungrounded conductor m\xE1s big","Table 250.66 o 12.5% si >1100 kcmil cu"],correct:3,explanation:"NEC 250.24(C)(1) \u2014 el neutral debe ser al menos el tama\xF1o de Table 250.66, y para conductors >1100 kcmil copper debe ser \u226512.5% del \xE1rea del largest ungrounded. Esto asegura capacidad de fault return.",reference:"NEC 250.24(C)(1)"},{category:"Protecci\xF3n Contra Sobrecorriente",difficulty:"easy",q:"NEC Article 240 cubre overcurrent protection. \xBFCu\xE1l es el prop\xF3sito principal de un breaker seg\xFAn 240.1?",options:["Desconectar loads para mantenimiento only","Proteger conductors/equipos contra temps","Medir amperaje consumido del circuito","Limitar fluctuaciones de voltage durante"],correct:1,explanation:"NEC 240.1 Informational Note \u2014 overcurrent protection abre el circuit antes de que la corriente cause temperature excesivo que da\xF1e la insulation o cree riesgo de fuego. No es para protecci\xF3n personal (eso es GFCI).",reference:"NEC 240.1"},{category:"Protecci\xF3n Contra Sobrecorriente",difficulty:"easy",q:"Seg\xFAn NEC 240.6(A), \xBFcu\xE1l de estos NO es un 'standard ampere rating' de breaker?",options:["15 A breaker standard rating per 240.6","25 A breaker standard rating per 240.6","35 A breaker standard rating per 240.6","45 A breaker NO standard... wait, it is"],correct:3,explanation:"NEC 240.6(A) lista los standard sizes: 15, 20, 25, 30, 35, 40, 45... wait, 45 S\xCD es standard. Los no-standards son tama\xF1os como 22A, 33A. La pregunta correcta ser\xEDa 33A. Standards: 15, 20, 25, 30, 35, 40, 45, 50, 60, 70, 80, 90, 100...",reference:"NEC 240.6(A)"},{category:"Protecci\xF3n Contra Sobrecorriente",difficulty:"easy",q:"Un 'standard ampere rating' NO incluido en NEC 240.6(A) es:",options:["15 A standard rating listed en 240.6(A)","22 A NO es standard rating per 240.6(A)","20 A standard rating listed en 240.6(A)","30 A standard rating listed en 240.6(A)"],correct:1,explanation:"NEC 240.6(A) lista 15, 20, 25, 30, 35, 40, 45, 50, 60, 70... El 22A no es standard \u2014 ser\xEDa non-standard. Por 240.4(B) se puede usar el next standard size up si el conductor ampacity no coincide con standard.",reference:"NEC 240.6(A)"},{category:"Protecci\xF3n Contra Sobrecorriente",difficulty:"medium",q:"NEC 240.4(B) 'next standard size up' permite subir al siguiente breaker size cuando la ampacidad del conductor no coincide con un standard rating. \xBFHasta qu\xE9 tama\xF1o aplica esta regla?",options:["Hasta 100 A next-standard-size-up rule","Hasta 200 A next-standard-size-up rule","Hasta 400 A next-standard-size-up rule","Hasta 800 A next-standard-size-up rule"],correct:3,explanation:"NEC 240.4(B) permite next-standard-size-up solo hasta 800A. Arriba de 800A debe coincidir exactamente o bajar. Aplica cuando conductor ampacity cae entre dos standards y el circuito no es para receptacles.",reference:"NEC 240.4(B)"},{category:"Protecci\xF3n Contra Sobrecorriente",difficulty:"medium",q:"Para circuitos con receptacles, la regla 'next size up' del 240.4(B) NO aplica \u2014 en este caso el OCPD debe:",options:["OCPD siempre 20A para receptacle circuits","OCPD igual o menor a ampacidad conductor","OCPD 125% de la carga continua estimada","OCPD igual al breaker principal feeder up"],correct:1,explanation:"NEC 240.4(B)(1) \u2014 receptacle circuits no permiten next-size-up. El OCPD debe ser \u2264 ampacidad del conductor. Esto previene que alguien enchufe una carga que el wire no aguanta.",reference:"NEC 240.4(B)"},{category:"Protecci\xF3n Contra Sobrecorriente",difficulty:"medium",q:"Un breaker marcado 'SWD' (Switching Duty) se requiere cuando:",options:["Usado como disconnect motor 430 branch","Switch de fluorescent lighting 120V HID","Protecci\xF3n de circuitos computadoras CPU","Panel trif\xE1sico 208Y comercial general"],correct:1,explanation:"NEC 240.83(D) exige breakers marcados 'SWD' o 'HID' cuando se usan para switching de fluorescent lighting de 120V (o HID). Los breakers regulares no est\xE1n rated para el inrush repetitivo de switching frecuente.",reference:"NEC 240.83(D)"},{category:"Protecci\xF3n Contra Sobrecorriente",difficulty:"medium",q:"Seg\xFAn NEC 240.21(B), un feeder tap de 10-ft puede ser sin overcurrent protection en su inicio si:",options:["Ampacity tap \u226510% OCPD, termina single","Solo en aplicaciones residenciales homes","Solo con conductors menores a 6 AWG cu","Nunca se permite un tap sin OCPD start"],correct:0,explanation:"NEC 240.21(B)(1) \u2014 10-ft tap rule: la ampacidad del tap \u22651/10 del OCPD principal, no sale del edificio, tiene su propio OCPD al final, y no excede 10 ft de largo. Muy \xFAtil para disconnects adyacentes al panel.",reference:"NEC 240.21(B)(1)"},{category:"Protecci\xF3n Contra Sobrecorriente",difficulty:"medium",q:"La regla de 25-ft tap de NEC 240.21(B)(2) requiere que la ampacidad del tap sea al menos:",options:["1/2 del feeder OCPD para 25-ft tap rule","1/3 del feeder OCPD para 25-ft tap rule","1/4 del feeder OCPD para 25-ft tap rule","Igual al feeder OCPD rating completo up"],correct:1,explanation:"NEC 240.21(B)(2) \u2014 25-ft tap: ampacidad del tap \u22651/3 del OCPD del feeder principal, termina en un OCPD que limite al ampacidad del tap, conductors protected de damage. Muy \xFAtil en installs industriales.",reference:"NEC 240.21(B)(2)"},{category:"Protecci\xF3n Contra Sobrecorriente",difficulty:"hard",q:"NEC 240.87 requiere reducci\xF3n de arc energy (como zone-selective interlocking o energy-reducing maintenance switch) en breakers con rating \u2265:",options:["400 A breaker rating seg\xFAn 240.87 NEC","600 A breaker rating seg\xFAn 240.87 NEC","800 A breaker rating seg\xFAn 240.87 NEC","1200 A breaker rating seg\xFAn 240.87 NEC"],correct:3,explanation:"NEC 240.87 aplica a circuit breakers con rating de 1200A o m\xE1s. Exige uno de: ZSI, energy-reducing maintenance switch, energy-reducing active arc flash mitigation, o instantaneous trip. Prop\xF3sito: reducir exposure de arc flash.",reference:"NEC 240.87"},{category:"Protecci\xF3n Contra Sobrecorriente",difficulty:"hard",q:"El Interrupting Rating (AIC) de un breaker debe ser:",options:["Al menos igual a available short-circuit","10% del breaker trip rating continuous","Igual al breaker trip rating operating","No importa si el breaker tiene GFCI"],correct:0,explanation:"NEC 110.9 exige que equipos interrupting (breakers, fusibles) tengan rating \u2265 al available fault current. Si el breaker es 10kAIC y el fault current es 15kA, el breaker puede explotar catastr\xF3ficamente \u2014 es un code violation peligroso.",reference:"NEC 110.9"},{category:"Protecci\xF3n Contra Sobrecorriente",difficulty:"hard",q:"Series-rated combinations (breaker + upstream breaker) seg\xFAn NEC 240.86 requieren:",options:["Marcado en el field por installer solo","Tested/listed fabricante + field-marked","Solo para aplicaciones residenciales cort","No se permite en servicios nuevos code"],correct:1,explanation:"NEC 240.86(B) \u2014 series ratings deben ser tested, listed, y field-marked con la combinaci\xF3n espec\xEDfica. Permite usar breakers downstream con AIC menor al fault current si el upstream breaker limita la energ\xEDa.",reference:"NEC 240.86"},{category:"Protecci\xF3n Contra Sobrecorriente",difficulty:"medium",q:"Un conductor 6 AWG copper THHN en raceway, terminal 75\xB0C rated, tiene ampacidad 65A. La continuous load es 50A + 10A non-continuous. \xBFQu\xE9 breaker se selecciona?",options:["60 A (ampacity limit sin next-size rule)","70 A aplicando next-size-up rule 240.4(B)","80 A basado en THHN columna 90\xB0C solo","50 A undersize para la continuous load"],correct:1,explanation:"Minimum OCPD = (50 \xD7 1.25) + 10 = 72.5A. Siguiente standard = 80A. PERO el conductor es 65A a 75\xB0C, entonces el next-size-up rule (240.4B) permite 70A (standard arriba de 65A). Como 70A > 72.5A no cumple... se requiere conductor m\xE1s grande o breaker de 80A con conductor mayor.",reference:"NEC 210.20(A), 240.4(B)"},{category:"Paneles y Services",difficulty:"easy",q:"Seg\xFAn NEC 230.70(A), el service disconnect debe instalarse:",options:["En cualquier lugar dentro de la dwelling","Nearest al point entrance service cond","Siempre en el garage de la residencia","Siempre outdoor en la pared exterior"],correct:1,explanation:"NEC 230.70(A)(1) \u2014 el service disconnect debe estar at a readily accessible location, nearest to the point of entrance de los service conductors, afuera o inside. No se permite que los service conductors unfused viajen largo dentro del edificio.",reference:"NEC 230.70(A)"},{category:"Paneles y Services",difficulty:"easy",q:"\xBFCu\xE1ntos service disconnects se permiten por building seg\xFAn NEC 230.71 (2020/2023)?",options:["Un solo disconnect permitido por building","M\xE1x 6 en un solo panel agrupado (viejo)","M\xE1x 6 en enclosures separados agrupados","Cada disconnect en enclosure separado own"],correct:3,explanation:"NEC 230.71(B) \u2014 cambio del 2020/2023 \u2014 m\xE1ximo 6 disconnects, pero AHORA cada uno debe estar en su propio enclosure separado. La vieja regla del 'six handle rule in one panel' cambi\xF3. Muy examinado.",reference:"NEC 230.71(B)"},{category:"Paneles y Services",difficulty:"easy",q:"La ampacity m\xEDnima del service para una dwelling unit residencial seg\xFAn NEC 230.79(C) es:",options:["60 A m\xEDnimo para one-family dwelling","100 A m\xEDnimo one-family dwelling 3-wire","150 A m\xEDnimo para one-family dwelling","200 A m\xEDnimo para one-family dwelling"],correct:1,explanation:"NEC 230.79(C) \u2014 one-family dwelling debe tener m\xEDnimo 100A service 3-wire. Antes del 2023 era la regla general; ahora aplica espec\xEDficamente a one-family dwellings. La tendencia moderna es 200A por EVs y heat pumps.",reference:"NEC 230.79(C)"},{category:"Paneles y Services",difficulty:"medium",q:"NEC 220.82 (Optional Calculation for Dwelling Unit) aplica cuando el service es:",options:["Menor a 100A 3-wire dwelling service","M\xEDnimo 100A 3-wire dwelling single-fam","Solo trif\xE1sico industrial/comercial loads","Solo dwellings con heat pump el\xE9ctrico"],correct:1,explanation:"NEC 220.82 \u2014 optional method para dwelling single-family con servicio m\xEDnimo 100A 3-wire. Usa factor 100% a los primeros 10 kVA y 40% al resto de general load, m\xE1s ajustes para heating/AC. A menudo resulta en un service m\xE1s chico que el standard method.",reference:"NEC 220.82"},{category:"Paneles y Services",difficulty:"medium",q:"Para calcular load de general lighting en dwelling seg\xFAn NEC Table 220.42(A), el factor unit load es:",options:["2 VA por sq ft para dwelling general","3 VA por sq ft para dwelling general","5 VA por sq ft para dwelling general","10 VA por sq ft para dwelling general"],correct:1,explanation:"NEC Table 220.42(A) (antes 220.12) \u2014 3 VA/sq ft para dwelling units. Para office buildings es 3.5, stores 3, hospitals 2. Se usa el \xE1rea habitable (no garage ni porches no habitables).",reference:"NEC 220.42"},{category:"Paneles y Services",difficulty:"medium",q:"NEC 210.11(C) requiere m\xEDnimo CU\xC1NTOS small-appliance branch circuits 20A en una cocina residencial:",options:["Un circuito dedicado 20A small appliance","Dos circuitos dedicados 20A small appl","Tres circuitos dedicados 20A small appl","Cuatro circuitos dedicados 20A small ap"],correct:1,explanation:"NEC 210.11(C)(1) \u2014 m\xEDnimo 2 small-appliance branch circuits 20A para los receptacles de kitchen, pantry, breakfast, dining. No pueden servir otras \xE1reas ni lighting.",reference:"NEC 210.11(C)(1)"},{category:"Paneles y Services",difficulty:"medium",q:"NEC 210.11(C)(2) exige al menos cu\xE1ntos circuits dedicados al laundry en una dwelling unit:",options:["No se requiere circuito dedicado laundry","Un circuito 15A dedicado laundry only","Un circuito 20A dedicado laundry only","Dos circuitos 20A dedicados laundry room"],correct:2,explanation:"NEC 210.11(C)(2) \u2014 m\xEDnimo un circuito 20A dedicado para laundry receptacles. No puede servir otras cargas. El washer solo usa ~10A pero el circuito dedicado previene breaker trips cuando hay carga.",reference:"NEC 210.11(C)(2)"},{category:"Paneles y Services",difficulty:"medium",q:"NEC 210.11(C)(3) requiere un branch circuit dedicado para el bathroom. \xBFAmperaje?",options:["15 A dedicado bathroom receptacles only","20 A dedicado bathroom receptacles only","30 A dedicado bathroom receptacles only","No se requiere circuito dedicado para"],correct:1,explanation:"NEC 210.11(C)(3) \u2014 branch circuit 20A dedicado para bathroom receptacles. Puede servir m\xFAltiples ba\xF1os, pero no puede servir otras cargas como lighting si solo alimenta un ba\xF1o. Adem\xE1s todos son GFCI.",reference:"NEC 210.11(C)(3)"},{category:"Paneles y Services",difficulty:"medium",q:"La altura m\xE1xima del highest circuit breaker handle en un panel seg\xFAn NEC 240.24(A) debe ser:",options:["5 ft 6 in altura m\xE1xima breaker handle","6 ft 7 in (2.0 m) m\xE1x breaker handle","7 ft 0 in altura m\xE1xima breaker handle","No hay l\xEDmite de altura para el handle"],correct:1,explanation:"NEC 240.24(A) \u2014 el center del operating handle del OCPD m\xE1s alto no puede exceder 6 ft 7 in (2.0 m) sobre el piso o working platform. Excepciones para equipos de alta capacidad con permanent platforms.",reference:"NEC 240.24(A)"},{category:"Paneles y Services",difficulty:"hard",q:"Calcula demand load para un dwelling con 2400 sq ft, 2 small-appliance circuits, 1 laundry, range de 12 kW, water heater 4.5 kW, dryer 5 kW. (Standard method, general lighting + sa + laundry a primer 3000 VA @ 100%, resto @ 35%)",options:["Aproximadamente 100A service sufficient","Aproximadamente 150A service necesario","Aproximadamente 200A service necesario","Aproximadamente 250A service necesario"],correct:0,explanation:"General lighting: 2400 \xD7 3 = 7200 VA. SA: 2 \xD7 1500 = 3000. Laundry: 1500. Subtotal: 11,700 VA. Demand: 3000@100% + 8700@35% = 6045 VA. Range @ 8000 VA (Table 220.55). Dryer @ 5000 VA min. WH 4500. Total ~23,545 VA / 240V = 98A. Service 100A suficiente.",reference:"NEC 220.82"},{category:"Paneles y Services",difficulty:"hard",q:"Seg\xFAn NEC 408.36, un lighting and appliance panelboard est\xE1 limited a cu\xE1ntos overcurrent devices m\xE1ximo:",options:["30 max OCPDs lighting/appliance panel","40 max OCPDs lighting/appliance panel","42 max OCPDs lighting/appliance panel","Sin l\xEDmite en NEC 2020/2023 versions"],correct:3,explanation:"NEC 2020/2023 elimin\xF3 el l\xEDmite de 42 circuit panelboard. Ahora la cantidad de OCPDs la determina el fabricante y la listing del panel. Esta fue una de las reformas del 2020 \u2014 antes era exactamente 42.",reference:"NEC 408.36"},{category:"Paneles y Services",difficulty:"hard",q:"Un feeder a un sub-panel tiene OCPD de 100A. El conductor es 3 AWG copper THHN (rating 100A @ 75\xB0C). Seg\xFAn NEC 408.36, el panel sub-alimentado debe tener rating m\xEDnimo de:",options:["60 A bus rating panel sub-alimentado min","100 A bus rating panel sub-alimentado","125 A bus rating (125% del breaker fed)","El rating del main breaker del sub-pan"],correct:1,explanation:"NEC 408.36 \u2014 panelboard bus rating \u2265 al OCPD que lo protege. Si el feeder breaker es 100A, el bus del sub-panel debe ser m\xEDnimo 100A. No necesita main breaker interno (a menos que tenga >6 OCPDs o est\xE9 en dwelling separated structure).",reference:"NEC 408.36"},{category:"Motores y Controles",difficulty:"easy",q:"NEC 430.22 \u2014 la ampacidad del conductor para un single motor continuos debe ser:",options:["100% del FLA motor continuous duty rate","115% del FLA motor continuous duty rate","125% del FLA motor continuous duty rate","200% del FLA motor continuous duty rate"],correct:2,explanation:"NEC 430.22(A) \u2014 single motor debe tener conductors sized a 125% del Full Load Amps (FLA) del Table 430.247-250, no el nameplate. Esto es para handle el starting y running continuous sin overheating.",reference:"NEC 430.22"},{category:"Motores y Controles",difficulty:"easy",q:"Para seleccionar el branch-circuit short-circuit OCPD de un motor, se usa el FLC de NEC Table 430.247-250 y la Table 430.52. Para un inverse-time breaker en motor standard, el m\xE1ximo es:",options:["125% del FLC para inverse-time breaker","175% del FLC para inverse-time breaker","250% del FLC para inverse-time breaker","800% del FLC (instantaneous trip MCP)"],correct:2,explanation:"NEC Table 430.52(C)(1) \u2014 Inverse time breaker permite hasta 250% del FLC para motores AC est\xE1ndar. Los instantaneous trip (motor circuit protectors) permiten 800%-1300%. No es el overload \u2014 es el SHORT-CIRCUIT protection.",reference:"NEC 430.52"},{category:"Motores y Controles",difficulty:"medium",q:"Los motor overload protectors (heaters, electronic overloads) se sized a cu\xE1nto del nameplate FLA seg\xFAn NEC 430.32 para un motor con service factor 1.15 o mayor?",options:["100% del FLA nameplate del motor only","115% del FLA nameplate (SF<1.15 motor)","125% del FLA nameplate (SF\u22651.15 motor)","150% del FLA nameplate setup incorrect"],correct:2,explanation:"NEC 430.32(A)(1) \u2014 motores con SF\u22651.15 o temp rise\u226440\xB0C: overload = 125% del nameplate FLA. Para motores con SF<1.15: 115%. Esta es la protecci\xF3n de overload, DIFERENTE al short-circuit de 430.52.",reference:"NEC 430.32(A)(1)"},{category:"Motores y Controles",difficulty:"medium",q:"NEC 430.102(B) \u2014 el motor disconnect debe estar:",options:["M\xE1ximo a 5 ft del motor driven machine","Within sight del motor o remote lockable","Siempre adjacente al panel MLO main","En el techo del mechanical room area"],correct:1,explanation:"NEC 430.102(B)(1) \u2014 disconnect debe estar in sight from motor y driven machinery, O permite remote si es capable of being locked in open position. 'In sight' = visible y dentro de 50 ft.",reference:"NEC 430.102(B)"},{category:"Motores y Controles",difficulty:"medium",q:"Para HVAC equipment (AC/heat pump), el nameplate muestra MCA=28.5 y MOP=50. El contratista debe instalar:",options:["Conductors 28.5A, 30A HACR breaker set","Conductors \u2265MCA 28.5A, breaker \u226450A max","Conductors 50A 6 AWG, 50A breaker set","Conductors 14 AWG, 40A breaker setup"],correct:1,explanation:"MCA (Minimum Circuit Ampacity) define el conductor \u2014 10 AWG @ 75\xB0C = 35A \u2265 28.5A MCA. MOP (Maximum Overcurrent Protection) es el breaker M\xC1XIMO = 50A. Se puede usar breaker menor (30A, 35A, 40A, 45A) si soporta el LRA \u2014 pero nunca arriba de 50A.",reference:"NEC 440.4, 440.22"},{category:"Motores y Controles",difficulty:"medium",q:"NEC 440.14 \u2014 el disconnect de un HVAC unit (AC condenser) debe estar instalado:",options:["Dentro del edificio cerca del panel ML","Within sight readily accessible del AC","Siempre en el techo del edificio rooftop","Dentro de la unidad misma del condensor"],correct:1,explanation:"NEC 440.14 \u2014 el disconnect debe estar in sight y readily accessible from the A/C equipment. Normalmente es el non-fused pull-out a 1-2 ft del condenser. Su prop\xF3sito: servicing seguro del compressor y fan.",reference:"NEC 440.14"},{category:"Motores y Controles",difficulty:"medium",q:"Para un hermetic refrigerant motor-compressor, las overload protections se basan en:",options:["Rated-load current (RLA) del nameplate","Horsepower del motor hermetic compressor","Locked-rotor current directo del motor","Voltaje de operaci\xF3n del motor hermetic"],correct:0,explanation:"NEC 440.52 \u2014 overload protection basado en 140% del RLA o menos (con overload relay). RLA se define espec\xEDficamente para hermetic compressors (diferente de FLA de motores regulares). Viene del nameplate.",reference:"NEC 440.52"},{category:"Motores y Controles",difficulty:"hard",q:"Un motor de 25 HP 480V 3-phase tiene FLC de tabla = 34A. Branch-circuit conductors m\xEDnimos (125% \xD7 34):",options:["34 A conductors (8 AWG 90\xB0C insufficient)","42.5 A conductors (8 AWG 75\xB0C = 50A ok)","68 A conductors (4 AWG oversized mucho)","85 A conductors (3 AWG muy oversized)"],correct:1,explanation:"NEC 430.22 \u2014 125% \xD7 34 = 42.5A. El 8 AWG copper @ 75\xB0C = 50A, suficiente. 10 AWG @ 75\xB0C = 35A insuficiente. Usa FLC de Table 430.250, no el nameplate. Terminal a 75\xB0C t\xEDpicamente.",reference:"NEC 430.22, 430.250"},{category:"Motores y Controles",difficulty:"hard",q:"Para el motor anterior (25 HP, FLC=34A), el branch-circuit short-circuit protection usando inverse-time breaker (250% del FLC) ser\xEDa:",options:["30 A (undersize, motor no arrancar\xE1 well)","60 A (insuficiente para inverse time 250%)","90 A (pr\xF3ximo standard arriba de 85A ok)","125 A (permitido con hard-start solo)"],correct:2,explanation:"250% \xD7 34A = 85A. No es un standard size. NEC 430.52(C)(1) Exception 1 permite subir al next standard size = 90A. Si el motor no arranca, se puede subir hasta 400% (136A \u2192 150A standard).",reference:"NEC 430.52(C)"},{category:"Motores y Controles",difficulty:"hard",q:"Un feeder para m\xFAltiples motores seg\xFAn NEC 430.24 debe tener ampacidad m\xEDnima de:",options:["Suma simple de todos los FLC motors run","125% FLC motor mayor + 100% otros FLC","Suma de FLC \xD7 125% de todos los motors","Igual al FLC del motor m\xE1s grande only"],correct:1,explanation:"NEC 430.24 \u2014 feeder conductor ampacity \u2265 125% del FLC del motor m\xE1s grande + 100% de los FLC de los dem\xE1s motores. El starting current del motor m\xE1s grande es la preocupaci\xF3n primaria.",reference:"NEC 430.24"},{category:"GFCI / AFCI",difficulty:"easy",q:"NEC 210.8(A) requiere GFCI protection en receptacles 125V de dwellings en cu\xE1les locations:",options:["Solo bathrooms de dwelling receptacles","Bathrooms, garages, outdoor, kitchens+","Solo exteriores dwelling receptacles set","Solo outlets cerca de agua grifo/sink"],correct:1,explanation:"NEC 210.8(A) es una lista extensa: bathrooms, garages, outdoors, crawl spaces, unfinished basements, kitchens (all counter outlets), within 6 ft de lavabo/bathtub, laundry, boathouses, sump pump areas. NEC 2023 expandi\xF3 a\xFAn m\xE1s.",reference:"NEC 210.8(A)"},{category:"GFCI / AFCI",difficulty:"easy",q:"La sensibilidad trip de un GFCI personnel protection (Class A) seg\xFAn UL 943 es:",options:["5 mA \xB1 1 mA nominal trip (Class A UL943)","30 mA nominal trip para GFPE equipment","100 mA nominal trip para special heat","1 A nominal trip (no existe Class A)"],correct:0,explanation:"Class A GFCI = 5 mA nominal (4-6 mA range). Trip time <25 ms. Los GFPE (equipment protection) son 30 mA \u2014 para heaters de roof/gutter. No confundir con AFCI que detecta arcs, no ground faults.",reference:"NEC 210.8, UL 943"},{category:"GFCI / AFCI",difficulty:"medium",q:"NEC 210.12(A) requiere AFCI protection en dwellings para todos los 120V single-phase 15A/20A branch circuits que sirven cu\xE1les rooms:",options:["Solo bedrooms de la dwelling habitables","Casi todas las rooms habitables except","Solo living room de la dwelling unit","Solo circuitos 15A de 120V dwelling"],correct:1,explanation:"NEC 210.12(A) lista: kitchens, family/living/dining/bedrooms, parlors, libraries, dens, sunrooms, closets, hallways, laundry, similar rooms. Exclusiones: bathrooms (GFCI), garages, outdoors \u2014 que tienen GFCI pero no AFCI.",reference:"NEC 210.12(A)"},{category:"GFCI / AFCI",difficulty:"medium",q:"La diferencia fundamental entre GFCI y AFCI:",options:["Son lo mismo, solo nombres diferentes","GFCI detecta ground-fault, AFCI arc sig","GFCI es 240V y AFCI es 120V only rule","AFCI es m\xE1s lento que GFCI personal"],correct:1,explanation:"GFCI = detecta desbalance entre hot y neutral indicando leakage a ground (personal safety). AFCI = detecta las firmas el\xE9ctricas de un arc el\xE9ctrico (fire prevention). Los combination AFCI/GFCI hacen ambas funciones.",reference:"NEC 210.8, 210.12"},{category:"GFCI / AFCI",difficulty:"medium",q:"NEC 210.8(B) \u2014 GFCI en 'other than dwelling units' (comercial), incluye outlets en:",options:["Solo bathrooms comerciales receptacles","Bathrooms, kitchens, rooftops, outdoor","Solo loading docks comerciales outlets","No se requiere GFCI en comercial units"],correct:1,explanation:"NEC 210.8(B) aplica muchos de los mismos locations en comercial, y el 2023 expandi\xF3 a all 125V-250V receptacles en estos locations (incluyendo 208V). Ahora los condensers comerciales expuestos tambi\xE9n requieren GFCI.",reference:"NEC 210.8(B)"},{category:"GFCI / AFCI",difficulty:"medium",q:"NEC 210.8(F) (a\xF1adido en 2020, refinado en 2023) requiere GFCI para outdoor outlets de equipos espec\xEDficos \u2014 como HVAC condensers \u2014 rated:",options:["Solo 125V receptacle outlet outdoor","125-250V single-phase outdoor dwelling","Solo trif\xE1sico comercial outdoor units","No aplica a HVAC outdoor dwelling ever"],correct:1,explanation:"NEC 210.8(F) exige GFCI en 125-250V single-phase outdoor outlets para dwellings. Incluye el outdoor disconnect del AC condenser. Algunas jurisdicciones han tenido nuisance tripping \u2014 NEC 2023 amendi\xF3 levemente.",reference:"NEC 210.8(F)"},{category:"GFCI / AFCI",difficulty:"hard",q:"NEC 210.8(E) \u2014 GFCI en crawl spaces para qu\xE9 outlets:",options:["No aplica GFCI a los crawl spaces ever","Todos los 125V 15/20A en crawl grade","Solo outlet del sump pump en crawl only","Solo crawl spaces con agua presente sum"],correct:1,explanation:"NEC 210.8(E) \u2014 todos los 125V single-phase 15/20A receptacles en crawl spaces at or below grade deben ser GFCI. Incluye el outlet del sump pump (antes exento, ahora requerido en 2023).",reference:"NEC 210.8(E)"},{category:"GFCI / AFCI",difficulty:"hard",q:"NEC 210.12(D) \u2014 el AFCI se requiere cuando se extiende un circuito existente en un dwelling por m\xE1s de 6 ft. \xBFD\xF3nde se puede instalar el AFCI?",options:["Solo en el breaker del panel el AFCI","Breaker AFCI o outlet branch-circuit 1st","Solo outlet type AFCI permitido NEC","No se requiere AFCI para extensions >6"],correct:1,explanation:"NEC 210.12(D) \u2014 extensions de circuits existentes >6 ft requieren AFCI. Se permite breaker AFCI, o combination AFCI en el first outlet extendido, o outlet branch-circuit type AFCI. Protege el nuevo wiring a\xF1adido.",reference:"NEC 210.12(D)"},{category:"Lugares Especiales",difficulty:"easy",q:"NEC Article 500 cubre Hazardous (Classified) Locations. Una Class I location contiene:",options:["Dust combustible en el aire ambiente","Gases/vapores inflamables en cantidad","Fibras/flyings combustibles textile mill","Solo agua en cantidad suficiente hazard"],correct:1,explanation:"NEC 500.5(B) \u2014 Class I = flammable gases/vapors (gasoline, propane, solvents). Class II = combustible dust (grain, plastic). Class III = fibers/flyings (textile mills, sawmills). Equipo espec\xEDfico listed para cada class.",reference:"NEC 500.5"},{category:"Lugares Especiales",difficulty:"easy",q:"En un bathroom residencial, \xBFqu\xE9 distancia debe estar un receptacle del borde de una tina o ducha seg\xFAn NEC?",options:["0 ft puede estar pegado a tub edge","3 ft m\xEDnimo de tub/shower horizontally","Dentro shower zone si es GFCI protect","Lejos del lavabo, m\xEDn 3 ft tub/shower"],correct:3,explanation:"NEC 406.9(C) \u2014 receptacles no se permiten dentro, arriba, ni a menos de 3 ft horizontalmente del bathtub o shower stall threshold. Debe ser GFCI protegido y estar lejos del splash zone.",reference:"NEC 406.9(C)"},{category:"Lugares Especiales",difficulty:"medium",q:"NEC 680 cubre Swimming Pools. \xBFQu\xE9 distancia debe estar un panel el\xE9ctrico del borde de un pool?",options:["3 ft horizontales del borde interior","5 ft horizontales del borde interior","10 ft horizontales del borde interior","25 ft horizontales del borde interior"],correct:2,explanation:"NEC 680.22(B) \u2014 el panelboard del pool pump u otros equipos deben estar a al menos 10 ft horizontales del borde interior del pool. Esto reduce el riesgo de ca\xEDda o contacto durante maintenance.",reference:"NEC 680.22(B)"},{category:"Lugares Especiales",difficulty:"medium",q:"Para un HVAC equipment room (mechanical room) comercial t\xEDpico, NEC 210.63 requiere:",options:["Un GFCI receptacle cerca del AC unit","Receptacle 125V 15/20A dentro 25 ft HVAC","Solo iluminaci\xF3n en mechanical room req","Iluminaci\xF3n de emergency en mech room"],correct:1,explanation:"NEC 210.63 \u2014 service receptacle 125V 15/20A dentro de 25 ft del equipo HVAC (en el mismo level y no a trav\xE9s de una puerta). Para tools de servicing. Debe ser GFCI si est\xE1 outdoor/rooftop.",reference:"NEC 210.63"},{category:"Lugares Especiales",difficulty:"medium",q:"NEC 210.63(A) fue expandido en 2020 \u2014 en rooftops con HVAC equipment, el service outlet debe ser GFCI y estar:",options:["En cualquier parte del edificio mismo","En el mismo level del rooftop (no abajo)","Solo adentro del edificio cerca del panel","No se requiere outlet en rooftops HVAC"],correct:1,explanation:"NEC 210.63(A) \u2014 el 125V service outlet DEBE estar en el mismo level que el HVAC equipment (ej. rooftop unit requiere rooftop outlet, no uno al nivel del s\xF3tano). T\xE9cnico no puede subir con extension cord.",reference:"NEC 210.63(A)"},{category:"Lugares Especiales",difficulty:"medium",q:"Un wet location seg\xFAn NEC 100 es:",options:["Solamente outdoors sin protecci\xF3n wet","Underground, concrete slab en contact","Solo bathrooms con saturaci\xF3n de agua","Cualquier cocina con humedad presente"],correct:1,explanation:"Article 100 define Wet Location: unprotected and subject to saturation with water or other liquids, underground, en concrete slabs en contacto con ground, outdoors no protegidos. Requiere boxes/devices weatherproof y WR listed.",reference:"NEC 100"},{category:"Lugares Especiales",difficulty:"medium",q:"En wet locations, los receptacles 15/20A 125V/250V deben ser:",options:["Solamente de pl\xE1stico weather-proof set","Weather-resistant (WR) + weatherproof cov","Met\xE1licos grounded weather-proof set","GFCI solamente sin necesidad WR cover"],correct:1,explanation:"NEC 406.9(B) \u2014 outdoor wet location receptacles deben ser WR listed. Cover weatherproof 'in-use' (bubble cover) cuando un plug puede estar conectado permanentemente (como lights). Adem\xE1s GFCI por 210.8.",reference:"NEC 406.9(B)"},{category:"Lugares Especiales",difficulty:"hard",q:"Una gasolinera \u2014 \xBFc\xF3mo se clasifica la zona dentro de 18 inches sobre grade y hasta 20 ft del dispenser horizontal?",options:["Class I Div 1 gasoline dispenser zone","Class I Div 2 dentro 20 ft dispenser","Class II Div 1 gasoline dispenser zone","Unclassified no hazard gasoline zone"],correct:1,explanation:"NEC Table 514.3(B)(1) \u2014 dentro de 20 ft del dispenser hasta 18 inches sobre grade es Class I Div 2. La zona debajo del dispenser a 4 ft es Div 1. Equipment en estas zonas debe ser listed explosion-proof o intrinsically safe.",reference:"NEC 514"},{category:"Lugares Especiales",difficulty:"hard",q:"NEC 547 \u2014 Agricultural Buildings requires equipotential bonding en \xE1reas de confinement para livestock \u2014 \xBFpara qu\xE9 prop\xF3sito?",options:["Reducir noise el\xE9ctrico en la barn dairy","Prevenir stray voltage/step en livestock","Ahorrar energ\xEDa en operaci\xF3n dairy farm","Facilitar maintenance el\xE9ctrico del barn"],correct:1,explanation:"NEC 547.10 \u2014 equipotential plane bonding en dairy barns, hog farms, etc. Las vacas son sensibles a <1V que reduce producci\xF3n de leche. Se embebe mesh en el concrete y se bonds a todos los metales accesibles.",reference:"NEC 547.10"},{category:"Lugares Especiales",difficulty:"hard",q:"Un walk-in cooler comercial (HVAC adjacent) con lighting \u2014 el interior es un damp o wet location?",options:["Dry location siempre interior walk-in","Damp location por condensaci\xF3n regular","Wet location siempre por humedad total","Depende del contenido cooler producto"],correct:1,explanation:"NEC 100 \u2014 walk-in coolers/freezers tienen condensaci\xF3n regular y se clasifican como damp location (partially protected pero sujeto a humedad moderada). Las luminarias deben ser damp-location listed m\xEDnimo, o wet si hay wash-down.",reference:"NEC 100, 410.10"},{category:"NEC 2023 C\xE1lculos",difficulty:"easy",q:"Para un motor trif\xE1sico de 10 HP a 230V seg\xFAn Table 430.250, la FLA es 28A. \xBFQu\xE9 ampacidad m\xEDnima deben tener los conductores del branch circuit (125%)?",options:["28A (FLA tabla sin aplicar 125% factor)","32A (aplicando 115% mal al FLA tabla)","35A (125% \xD7 28A FLA Table 430.250 cu)","40A (aplicando 143% sobre FLA incorrect)"],correct:2,explanation:"NEC 430.22 exige que los conductores del branch circuit de un motor continuous duty sean 125% de la FLA de la Table 430.250 (no la nameplate). 28A \xD7 1.25 = 35A m\xEDnimo de ampacity.",reference:"NEC 430.22, Table 430.250"},{category:"NEC 2023 C\xE1lculos",difficulty:"medium",q:"Servicio residencial 200A, 120/240V 1-phase. \xBFCu\xE1l es el tama\xF1o m\xEDnimo del conductor de cobre THWN-2 para el service entrance seg\xFAn Table 310.12 (dwelling services)?",options:["1/0 AWG cobre THWN-2 para service 200A","2/0 AWG cobre THWN-2 para service 200A","3/0 AWG cobre THWN-2 para service 200A","4/0 AWG cobre THWN-2 para service 200A"],correct:1,explanation:"NEC Table 310.12 (dwelling services and feeders, 2023) permite 2/0 AWG cobre o 4/0 AWG aluminio para un servicio de 200A en vivienda unifamiliar. Esta tabla es reducida respecto a Table 310.16 porque aplica diversity factor.",reference:"NEC Table 310.12"},{category:"NEC 2023 C\xE1lculos",difficulty:"medium",q:"C\xE1lculo de feeder residencial \u2014 carga general de iluminaci\xF3n para una casa de 2,400 sq ft. \xBFCu\xE1l es la carga calculada antes de aplicar demand factors?",options:["5,400 VA (2.25 VA/sq ft error calc)","6,000 VA (2.5 VA/sq ft error calculo)","7,200 VA (3 VA/sq ft \xD7 2,400 correcto)","8,400 VA (3.5 VA/sq ft office error)"],correct:2,explanation:"NEC 220.12 \u2014 unit load dwelling es 3 VA/sq ft. 2,400 \xD7 3 = 7,200 VA de iluminaci\xF3n general y recept\xE1culos. Despu\xE9s se aplican demand factors de Table 220.42 (100% primeros 3,000 VA, 35% siguientes).",reference:"NEC 220.12, Table 220.42"},{category:"NEC 2023 C\xE1lculos",difficulty:"hard",q:"Motor trif\xE1sico 25 HP a 460V con FLA 34A (Table 430.250). Usando un breaker inverse-time, \xBFcu\xE1l es el tama\xF1o m\xE1ximo del OCPD seg\xFAn Table 430.52?",options:["85A OCPD (175% FLC no standard error)","100A OCPD (300% FLC muy excesivo error)","85A OCPD (250% \xD7 34A FLC table 430.52)","150A OCPD (aplicando 440% incorrect)"],correct:2,explanation:"Table 430.52 permite para motores trif\xE1sicos con inverse-time breaker hasta 250% de la FLA. 34A \xD7 2.50 = 85A m\xE1ximo. Si no es tama\xF1o est\xE1ndar, 430.52(C)(1) Exc 1 permite subir al pr\xF3ximo est\xE1ndar superior (90A).",reference:"NEC Table 430.52, 430.52(C)(1)"},{category:"NEC 2023 C\xE1lculos",difficulty:"medium",q:"Para una cocina residencial, NEC 220.55 exige calcular la range el\xE9ctrica de 12kW seg\xFAn Table 220.55. \xBFCu\xE1l es la carga demandada para UN range de 12kW?",options:["8 kW demand (Column C 1 appliance 12kW)","10 kW demand (sin aplicar table 220.55)","12 kW demand (al 100% nameplate rate)","15 kW demand (125% del nameplate)"],correct:0,explanation:"NEC Table 220.55 Column C \u2014 para un range de 12kW o menor la demand es 8kW (Column C, one appliance). Este demand factor reconoce que los burners no operan todos al m\xE1ximo simult\xE1neamente.",reference:"NEC Table 220.55"},{category:"NEC 2023 C\xE1lculos",difficulty:"hard",q:"Dwelling unit con AC de 5-ton (40A) y heat el\xE9ctrico de 10kW a 240V. Para el service calc NEC 220.82, \xBFqu\xE9 carga se incluye de estos dos?",options:["Suma ambos AC y heat (40A + 41.7A)","Solo el mayor (heat 10kW single 220.82)","65% de la suma de AC + heating loads","100% del AC + 40% del heat combined"],correct:1,explanation:"NEC 220.82(C) \u2014 para el optional dwelling calc solo se incluye el MAYOR entre AC y heating (no ambos) porque no operan simult\xE1neamente. Heat 10,000/240 = 41.7A > 40A AC, entonces se usa el heat al 100%.",reference:"NEC 220.82(C)"},{category:"Grounding y Bonding",difficulty:"easy",q:"El grounding electrode conductor (GEC) para un servicio de 200A residencial con conductor de entrada de 2/0 AWG cobre \u2014 \xBFcu\xE1l es el tama\xF1o m\xEDnimo seg\xFAn Table 250.66?",options:["#8 AWG copper GEC service 200A 2/0","#6 AWG copper GEC service 200A 2/0","#4 AWG copper GEC service 200A 2/0","#2 AWG copper GEC service 200A 2/0"],correct:2,explanation:"NEC Table 250.66 \u2014 para service conductors de 2/0 o 3/0 cobre, el GEC m\xEDnimo es #4 AWG cobre. Si el GEC termina en un ground rod solamente, 250.66(A) limita a #6 AWG m\xE1ximo requerido.",reference:"NEC Table 250.66"},{category:"Grounding y Bonding",difficulty:"medium",q:"Seg\xFAn NEC 250.52(A), \xBFcu\xE1l de estos NO es un grounding electrode reconocido?",options:["Metal water pipe 10+ ft contact earth","Concrete-encased electrode Ufer 20 ft","Ground ring cobre #2 m\xEDnimo 20 ft en","Rebar suelto 4 ft enterrado en jard\xEDn"],correct:3,explanation:"NEC 250.52(A) lista electrodes permitidos: metal water pipe, concrete-encased, ground ring, rod/pipe electrodes (8 ft m\xEDn), plate electrodes. Rebar suelto de 4 ft no cumple los requisitos \u2014 los rod electrodes deben ser 8 ft m\xEDnimo.",reference:"NEC 250.52(A)"},{category:"Grounding y Bonding",difficulty:"medium",q:"Un ground rod de 8 ft instalado y medido con 30 ohmios de resistencia. Seg\xFAn NEC 250.53(A)(2), \xBFqu\xE9 se requiere?",options:["Aceptar el rod ya cumple <25 ohms NEC","Instalar segundo rod \u22656 ft del primero","Reemplazar por copper-clad de 10 ft new","Agregar sal alrededor para bajar ohms"],correct:1,explanation:"NEC 250.53(A)(2) \u2014 si un rod no logra \u226425 ohms, debe agregarse un segundo electrodo, separado m\xEDnimo 6 pies del primero. Despu\xE9s del segundo rod NO se requiere medir nuevamente (se considera cumplido).",reference:"NEC 250.53(A)(2)"},{category:"Grounding y Bonding",difficulty:"hard",q:"Equipment grounding conductor (EGC) para un branch circuit protegido con breaker de 60A seg\xFAn Table 250.122 \u2014 \xBFcu\xE1l es el tama\xF1o m\xEDnimo de cobre?",options:["#12 AWG EGC copper para OCPD 60A error","#10 AWG EGC copper para OCPD 60A table","#8 AWG EGC copper para OCPD 60A error","#6 AWG EGC copper para OCPD 60A error"],correct:1,explanation:"NEC Table 250.122 \u2014 para OCPD de 60A el EGC m\xEDnimo es #10 AWG cobre (#8 AWG aluminio). Nota importante: si los conductores de fase se upsize por voltage drop, el EGC tambi\xE9n debe upsize proporcionalmente (250.122(B)).",reference:"NEC Table 250.122"},{category:"Grounding y Bonding",difficulty:"medium",q:"En un service de 400A con main bonding jumper, \xBFd\xF3nde se hace la conexi\xF3n neutro-tierra seg\xFAn NEC 250.24?",options:["En cada subpanel downstream bond error","Solamente en el service disconnect main","En el transformer de utility secondary","En cada recept\xE1culo GFCI del dwelling"],correct:1,explanation:"NEC 250.24(A)(5) proh\xEDbe bonding del neutral al ground downstream del service disconnect. El main bonding jumper est\xE1 SOLO en el service. Downstream los neutros se mantienen aislados de tierra \u2014 previene corrientes paralelas en EGC.",reference:"NEC 250.24(A)(5), 250.142"},{category:"Motor Control",difficulty:"easy",q:"El disconnect del motor seg\xFAn NEC 430.102(B) debe estar ubicado:",options:["A la vista (in sight) del motor driven","En el panel principal siempre MLO main","Dentro de la maquinaria driven interno","Dentro del MCC enclosure solamente one"],correct:0,explanation:"NEC 430.102(B) exige un disconnect in sight del motor y la maquinaria que acciona. 'In sight' = visible y dentro de 50 ft. Esto permite al t\xE9cnico hacer LOTO local sin depender de un panel remoto.",reference:"NEC 430.102(B)"},{category:"Motor Control",difficulty:"medium",q:"Overload protection (thermal) para un motor continuous-duty con SF 1.15 se ajusta a qu\xE9 porcentaje de la nameplate FLA seg\xFAn NEC 430.32?",options:["100% nameplate FLA (SF 1.0 max error)","115% nameplate FLA (motor SF<1.15 only)","125% nameplate FLA (SF\u22651.15 motor only)","140% nameplate FLA (hermetic compressor)"],correct:2,explanation:"NEC 430.32(A)(1) \u2014 motores con service factor \u22651.15 o temp rise \u226440\xB0C permiten overload a 125% de la nameplate FLA (no de Table 430.250). Motores est\xE1ndar (SF 1.0) se limitan a 115%.",reference:"NEC 430.32(A)(1)"},{category:"Motor Control",difficulty:"medium",q:"Para un motor 3-phase 15HP a 460V (FLA 21A) \u2014 el disconnect switch debe tener rating m\xEDnimo de:",options:["100% de FLA tabla 430.250 rating min","115% de FLA nameplate del motor rating","115% FLA Table 430.250 (disconnect amps)","No aplica regla, cualquier disco sirve"],correct:2,explanation:"NEC 430.110(A) exige que el motor disconnect switch tenga ampere rating m\xEDnimo de 115% de la FLA de Table 430.250 (no nameplate). 21A \xD7 1.15 = 24.15A \u2014 se redondea a 30A est\xE1ndar m\xEDnimo.",reference:"NEC 430.110(A)"},{category:"Motor Control",difficulty:"hard",q:"MCC (Motor Control Center) con m\xFAltiples motores \u2014 el feeder conductor sizing seg\xFAn NEC 430.24 es:",options:["Suma total FLA \xD7 1.25 para feeder MCC","Motor mayor \xD7 1.25 + suma FLA otros run","Motor m\xE1s grande \xD7 1.5 fixed multiplier","125% \xD7 (suma todos los FLA motors)"],correct:1,explanation:"NEC 430.24 \u2014 feeder para m\xFAltiples motores = 125% del FLA del motor m\xE1s grande + 100% del FLA de los dem\xE1s motores. Esto reconoce el starting surge del motor mayor mientras los otros ya est\xE1n running.",reference:"NEC 430.24"},{category:"Transformers",difficulty:"medium",q:"Transformer 75 kVA, 480V delta primario / 208Y/120V secundario. \xBFCu\xE1l es la corriente de FLA del primario?",options:["90A primario (75,000/(480\xD71.732) = 90A)","180A primario (error c\xE1lculo 2\xD7 factor)","208A primario (es el secundario 208V)","360A primario (error dividiendo por 208)"],correct:0,explanation:"F\xF3rmula trif\xE1sica: I = kVA \xD7 1000 / (V \xD7 \u221A3). Primario = 75,000 / (480 \xD7 1.732) = 75,000 / 831 = 90.2A. El secundario ser\xEDa 75,000 / (208 \xD7 1.732) = 208A.",reference:"NEC 450, f\xF3rmula b\xE1sica"},{category:"Transformers",difficulty:"medium",q:"Protecci\xF3n OCPD del primario de un transformer con corriente >9A \u2014 seg\xFAn NEC Table 450.3(B), \xBFcu\xE1l es el m\xE1ximo?",options:["100% de FLA primary OCPD transformer","125% con fuses primario transformer only","250% con breaker primary transformer","125% Table 450.3(B) primary \u22659A only"],correct:3,explanation:"NEC Table 450.3(B) \u2014 transformers menores a 1000V con primary-only protection y corriente \u22659A permiten OCPD m\xE1ximo 125% de la primary FLA (pr\xF3ximo est\xE1ndar superior si no es tama\xF1o comercial, 450.3(B) Note 1).",reference:"NEC Table 450.3(B)"},{category:"Transformers",difficulty:"hard",q:"Un transformer dry-type de 150 kVA ubicado en un edificio comercial \u2014 \xBFqu\xE9 distancia m\xEDnima de materiales combustibles requiere NEC 450.21?",options:["6 inches separaci\xF3n m\xEDnima combustibles","12 inches separaci\xF3n fija sin rating fire","No requirement si es menor a 112.5 kVA","12 inches combustibles o fire-resistant"],correct:3,explanation:"NEC 450.21(B) \u2014 dry-type transformers >112.5 kVA deben instalarse en transformer room de material fire-resistant, O mantener m\xEDnimo 12 inches de separaci\xF3n a combustibles. Alternativa: usar transformer listado Class 155 o superior con barrera.",reference:"NEC 450.21(B)"},{category:"Commercial Wiring Methods",difficulty:"easy",q:"Seg\xFAn Table 310.16, \xBFcu\xE1l es la ampacity de un conductor #10 AWG THHN cobre (90\xB0C) a 30\xB0C ambient?",options:["30A ampacity 90\xB0C insufficient #10 AWG","35A ampacity 75\xB0C columna Table 310.16","40A ampacity 90\xB0C columna Table 310.16","45A ampacity sobre 90\xB0C #10 AWG error"],correct:2,explanation:"Table 310.16 columna 90\xB0C \u2014 #10 AWG cobre THHN es 40A. Sin embargo, 110.14(C) limita las terminaciones a 60\xB0C (30A) o 75\xB0C (35A) seg\xFAn el equipment rating. Para breakers residenciales comunes = 30A m\xE1ximo.",reference:"NEC Table 310.16, 110.14(C)"},{category:"Commercial Wiring Methods",difficulty:"medium",q:"Cuatro (4) conductores portadores de corriente en un conduit \u2014 \xBFqu\xE9 ajuste de ampacidad aplica Table 310.15(C)(1)?",options:["100% sin derating para 4-6 CCCs error","80% derating para 4-6 CCCs table adjust","70% derating para 4-6 CCCs error ajust","50% derating para 4-6 CCCs error ajust"],correct:1,explanation:"Table 310.15(C)(1) \u2014 4 a 6 current-carrying conductors en raceway requieren derating al 80%. El neutral generalmente no cuenta (si carga balanceada), pero en sistemas con no-lineales (harmonics) s\xED cuenta como CCC.",reference:"NEC Table 310.15(C)(1)"},{category:"Commercial Wiring Methods",difficulty:"medium",q:"NEC 310.14(A)(3) \u2014 los conductores en ambient superior a 30\xB0C deben tener ampacity ajustada con:",options:["Tabla de demand factor para calc load","Ambient temp correction 310.15(B)(1)","No aplica ajuste de temperature factor","Fixed 80% siempre sin temp consideracion"],correct:1,explanation:"NEC Table 310.15(B)(1) contiene los correction factors para ambient >30\xB0C. Ejemplo: conductor 90\xB0C a 50\xB0C ambient = factor 0.82. En techos con sunlight exposure se aplica tambi\xE9n 310.15(B)(2) con adders.",reference:"NEC Table 310.15(B)(1)"},{category:"Commercial Wiring Methods",difficulty:"hard",q:"Un conduit EMT horizontal a 1 inch sobre techo con exposici\xF3n directa al sol. Seg\xFAn NEC 310.15(B)(2), \xBFqu\xE9 se suma a la temperatura ambiente?",options:["Nada, solo el ambient sin adder rooftop","22\xB0F (12\xB0C) adder 0.5-3.5 in roof sun","50\xB0F (27\xB0C) adder sin rooftop distance","Depende del color del techo reflective"],correct:1,explanation:"NEC Table 310.15(B)(2) \u2014 conduit 0.5 a 3.5 inches sobre rooftop con sun exposure adds 22\xB0F (12\xB0C) al ambient. Esto antes era 40\xB0F pero se redujo en NEC 2017. Considerar 30\xB0C ambient + 12\xB0C = 42\xB0C para ampacity correction.",reference:"NEC Table 310.15(B)(2)"},{category:"Conduit Fill",difficulty:"easy",q:"Seg\xFAn NEC Chapter 9 Table 1, \xBFcu\xE1l es el m\xE1ximo fill permitido para TRES o m\xE1s conductores en un conduit?",options:["31% fill m\xE1ximo para 3+ conductors wire","40% fill m\xE1ximo para 3+ conductors wire","53% fill m\xE1ximo para 3+ conductors wire","60% fill m\xE1ximo para 3+ conductors wire"],correct:1,explanation:"NEC Chapter 9 Table 1 \u2014 3 o m\xE1s conductores permiten 40% fill. 1 conductor = 53%, 2 conductores = 31% (para prevenir jamming). El 40% para 3+ es la regla m\xE1s com\xFAn en trabajo comercial.",reference:"NEC Chapter 9 Table 1"},{category:"Conduit Fill",difficulty:"medium",q:"Cuatro (4) conductores THHN #12 AWG (area 0.0133 sq in cada uno) \u2014 \xBFcu\xE1l es el tama\xF1o m\xEDnimo de EMT seg\xFAn Annex C, Table C.1?",options:["1/2 inch EMT (Annex C permite 9 #12)","3/4 inch EMT oversize para 4 #12 THHN","1 inch EMT muy oversize para 4 #12 THHN","1-1/4 in EMT muy oversize 4 #12 THHN"],correct:0,explanation:"NEC Annex C Table C.1 (EMT) \u2014 1/2 inch EMT permite hasta 9 THHN #12 AWG. 4 conductores #12 caben holgadamente. Annex C tabula directamente el n\xFAmero de conductores del mismo tama\xF1o por tipo de conduit.",reference:"NEC Annex C, Table C.1"},{category:"Conduit Fill",difficulty:"hard",q:"Un conduit con conductores de diferentes tama\xF1os (#8, #10, #12 mezclados) \u2014 \xBFc\xF3mo se calcula el fill?",options:["Usar Annex C directamente tabla only","Sumar \xE1reas Table 5 vs 40% Table 4 int","Usar solo el conductor m\xE1s grande only","No se permite mezclar tama\xF1os AWG mix"],correct:1,explanation:"Para conductors mixtos: sumar \xE1reas individuales de Table 5 (o 5A para compact) y comparar contra 40% del \xE1rea interna del conduit de Table 4. Annex C solo sirve cuando TODOS los conductores son del mismo tama\xF1o/tipo.",reference:"NEC Chapter 9 Tables 1, 4, 5"},{category:"Voltage Drop",difficulty:"medium",q:"NEC 210.19(A) Informational Note 4 recomienda que el voltage drop del branch circuit no exceda:",options:["1% m\xE1ximo recomendado branch circuit","3% m\xE1ximo recomendado branch circuit","5% m\xE1ximo solo branch circuit alone up","10% m\xE1ximo seg\xFAn Informational Note 4"],correct:1,explanation:"NEC 210.19(A) IN 4 (y 215.2 IN 2 para feeders) recomienda 3% m\xE1x en branch circuit y 5% total combinado (feeder + branch) para eficiencia razonable. NOTA: Es informacional, no mandatorio \u2014 pero Title 24 California lo exige mandatorio.",reference:"NEC 210.19(A) IN 4"},{category:"Voltage Drop",difficulty:"hard",q:"Circuit de 20A 120V cargado al 80% (16A), 150 ft one-way con #12 AWG cobre (K=12.9 \u03A9\xB7cmil/ft). \xBFCu\xE1l es el voltage drop aproximado?",options:["2.4V drop (2% del 120V base calc error)","4.8V drop (4% del 120V base calc error)","7.7V drop (~6.4% del 120V base calc 12)","12V drop (10% del 120V base calc error)"],correct:2,explanation:"VD = 2 \xD7 K \xD7 I \xD7 D / cmil. #12 AWG = 6,530 cmil. VD = 2 \xD7 12.9 \xD7 16 \xD7 150 / 6,530 = 61,920/6,530 = 9.48V. Aprox 7-8% \u2014 excede 3% recomendado. Soluci\xF3n: upgrade a #10 AWG para reducir a ~3%.",reference:"NEC 210.19 IN 4, f\xF3rmula VD"},{category:"Voltage Drop",difficulty:"medium",q:"Cuando se upsize un conductor por voltage drop, \xBFqu\xE9 m\xE1s debe aumentar proporcionalmente?",options:["El conduit siempre proporcional upsize","El EGC proporcional seg\xFAn 250.122(B)","El breaker al siguiente tama\xF1o standard","La altura del working space del panel"],correct:1,explanation:"NEC 250.122(B) \u2014 cuando se upsize ungrounded conductors por cualquier raz\xF3n (VD, parallel, etc.), el EGC debe upsize proporcionalmente por la misma ratio circular mil. Esto mantiene fault-clearing performance del ground fault loop.",reference:"NEC 250.122(B)"},{category:"HVAC Disconnect NEC 440",difficulty:"easy",q:"Un condensador de AC split residencial outdoor \u2014 \xBFd\xF3nde debe estar el disconnect seg\xFAn NEC 440.14?",options:["Dentro del home panel solamente dwell","Within sight readily accessible del AC","En el attic del home sobre el hallway","No se requiere disconnect separado AC"],correct:1,explanation:"NEC 440.14 \u2014 disconnect HVAC debe ser within sight (visible y \u226450 ft) del equipo AC y readily accessible. No puede estar detr\xE1s del equipo mismo. T\xEDpicamente se instala en pared adyacente al condensador outdoor.",reference:"NEC 440.14"},{category:"HVAC Disconnect NEC 440",difficulty:"medium",q:"Nameplate de condenser: MCA 24.5A, MOCP 40A max. \xBFQu\xE9 significa MOCP?",options:["Minimum Overcurrent Protection rating","Maximum Overcurrent Protection (m\xE1x)","Motor Output Current Peak nameplate","Minimum Operating Circuit Pressure psi"],correct:1,explanation:"MOCP = Maximum Overcurrent Protection. Es el tama\xF1o M\xC1XIMO del breaker o fuse que el fabricante permite para proteger el equipo. Usar m\xE1s grande anula la certificaci\xF3n UL. MCA (Min Circuit Ampacity) define el tama\xF1o m\xEDnimo del conductor.",reference:"NEC 440.4(B), nameplate marking"},{category:"HVAC Disconnect NEC 440",difficulty:"medium",q:"Air handler con electric heat strips 10kW y blower motor 1/2 HP \u2014 \xBFqu\xE9 calibre de conductor m\xEDnimo si MCA en nameplate = 48A?",options:["#10 AWG (35A 75\xB0C insufficient para 48A)","#8 AWG THHN (50A 75\xB0C suficiente 48A)","#6 AWG (65A 75\xB0C muy oversized 48A)","#4 AWG (85A 75\xB0C muy oversized 48A)"],correct:1,explanation:"NEC 440.32 y 440.33 \u2014 usar MCA del nameplate directamente para sizing conductor. MCA 48A requiere ampacidad \u226548A. #8 AWG THHN a 75\xB0C = 50A (Table 310.16). #10 AWG solo 35A \u2014 insuficiente.",reference:"NEC 440.32, Table 310.16"},{category:"HVAC Disconnect NEC 440",difficulty:"hard",q:"Split system con condensador outdoor 240V y air handler indoor con heat strips \u2014 \xBFrequieren disconnects separados?",options:["No, un disconnect sirve para todo split","S\xED, cada unit disconnect 440.14 + 424.19","Solo si supera 60A carga del equipment","Solo en aplicaciones comerciales split"],correct:1,explanation:"NEC 440.14 exige disconnect within sight del condenser outdoor, Y NEC 424.19 exige disconnect para los electric heat strips del air handler. Son cargas y ubicaciones diferentes \u2014 el single disconnect solo funciona si ambos est\xE1n within sight de uno.",reference:"NEC 440.14, 424.19"},{category:"GFCI/AFCI 2023",difficulty:"easy",q:"NEC 210.8(A) 2023 \u2014 \xBFen cu\xE1les \xE1reas residenciales se requiere GFCI protection para recept\xE1culos 125V?",options:["Solo ba\xF1os y cocinas dwelling GFCI all","Ba\xF1os, cocinas, garages, outdoor, crawl","Solo outdoor de la dwelling unit single","Solo ba\xF1os y outdoor de la dwelling un"],correct:1,explanation:"NEC 210.8(A) 2023 expandi\xF3 GFCI a: bathrooms, garages, outdoor, crawl, unfinished basements, kitchens, sinks (within 6 ft), boathouses, laundry, indoor damp/wet bar sinks, bathtub/shower area, dishwashers. Casi toda \xE1rea con humedad.",reference:"NEC 210.8(A)"},{category:"GFCI/AFCI 2023",difficulty:"medium",q:"NEC 210.8(F) NEW 2020/2023 \u2014 \xBFrequiere GFCI en equipment HVAC outdoor?",options:["No, exempt outdoor HVAC dwelling units","S\xED, outlets HVAC outdoor requieren GFCI","Solo si el equipo es mayor a 30A load","Solo en aplicaciones comerciales HVAC"],correct:1,explanation:"NEC 210.8(F) NEW \u2014 outlets (incluyendo hardwired) para outdoor HVAC equipment en dwelling requieren GFCI protection. Esto caus\xF3 problemas con trips falsos en algunas unidades 2020; fabricantes actualizaron equipos para compatibility.",reference:"NEC 210.8(F)"},{category:"GFCI/AFCI 2023",difficulty:"medium",q:"NEC 210.12(A) 2023 \u2014 AFCI protection requerida para branch circuits 120V 15/20A en dwellings en qu\xE9 \xE1reas?",options:["Solo bedrooms dwelling AFCI protection","Solo cocinas dwelling AFCI protection","Kitchen, family, dining, bedrooms, hall","Solo outdoor dwelling AFCI protection"],correct:2,explanation:"NEC 210.12(A) \u2014 AFCI protection requerida en casi todas las habitaciones habitables de una dwelling. Excepciones: ba\xF1os, garages, outdoor. El AFCI detecta arcing faults que anteceden fires \u2014 t\xEDpica causa de incendios residenciales.",reference:"NEC 210.12(A)"},{category:"GFCI/AFCI 2023",difficulty:"hard",q:"Dual-function breaker CAFCI/GFCI \u2014 \xBFcu\xE1ndo NO puede usarse?",options:["Nunca, dual-function es siempre OK use","Loads arcing normal (motors, vacuums)","Solo en aplicaciones 240V trif\xE1sicas big","En aplicaciones outdoor dwelling units"],correct:1,explanation:"Los dual-function CAFCI/GFCI pueden dar nuisance tripping con loads inductivos grandes (vacuums, universal motors, refrigeradores viejos). Soluci\xF3n: usar receptacle-type GFCI/AFCI solo downstream del outlet problem\xE1tico, o un CAFCI sin GFCI donde el code lo permita.",reference:"NEC 210.12, manufacturer guidance"},{category:"Emergency Systems NEC 700",difficulty:"medium",q:"Emergency system NEC 700 \u2014 la carga debe transferirse al source emergency en cu\xE1nto tiempo?",options:["1 segundo m\xE1ximo transfer emergency","10 segundos m\xE1ximo transfer emergency","30 segundos m\xE1ximo transfer emergency","2 minutos m\xE1ximo transfer emergency"],correct:1,explanation:"NEC 700.12 \u2014 emergency systems deben transferir carga en 10 segundos m\xE1ximo (dejando tiempo para arranque de generator). Legally required standby 701.12 permite hasta 60 segundos. Emergency cubre egress lighting, fire alarm, life safety.",reference:"NEC 700.12"},{category:"Emergency Systems NEC 700",difficulty:"medium",q:"\xBFQu\xE9 diferencia principal hay entre NEC 700 Emergency y NEC 701 Legally Required Standby?",options:["Ninguna diferencia, ambos son iguales","Emergency life safety 10s; standby 60s","Emergency solo en hospitales healthcare","Standby solo para homes dwelling units"],correct:1,explanation:"Emergency (700) = life safety cr\xEDtico con 10 sec transfer, circuits separados. Legally Required Standby (701) = requerido por autoridad pero no immediate life safety, 60 sec transfer. Optional Standby (702) = convenience, sin tiempo prescrito.",reference:"NEC 700, 701, 702"},{category:"Emergency Systems NEC 700",difficulty:"hard",q:"Wiring de emergency circuits NEC 700.10 \u2014 \xBFdeben mantenerse independientes de otros wiring?",options:["No, emergency comparte raceway normal","S\xED, independientes excepto conditions","Solo en hospitales healthcare emergency","Solo si voltage es mayor a 600V ac"],correct:1,explanation:"NEC 700.10(B) \u2014 emergency wiring debe mantenerse independiente de todo otro wiring y equipment. Excepciones: transition boxes at transfer switch, emergency loads en emergency panels, y 2 horas fire rated circuits. Esto previene que falla normal afecte emergency.",reference:"NEC 700.10(B)"},{category:"Hazardous Locations",difficulty:"medium",q:"Class I Division 1 vs Division 2 \u2014 \xBFcu\xE1l es la diferencia clave?",options:["Div 1 ignitable normal; Div 2 accident","Div 1 es m\xE1s barato que Div 2 setup","Div 2 es indoor solamente siempre rule","Div 1 es l\xEDquidos, Div 2 es gases only"],correct:0,explanation:"NEC 500.5 \u2014 Class I Div 1 = ignitable gases/vapors presentes continuously, intermittently, o periodically bajo normal operating conditions. Div 2 = solo bajo abnormal conditions (ruptured container, failure). Equipment Div 1 es m\xE1s costoso \u2014 explosion-proof certificado.",reference:"NEC 500.5"},{category:"Hazardous Locations",difficulty:"medium",q:"Seal fittings NEC 501.15 en Class I Div 1 \u2014 \xBFd\xF3nde se requieren?",options:["Solo al entrar al enclosure explosion","Dentro 18 in del enclosure + boundary","Solo entre cuartos del edificio hazard","No se requieren sellos en Div 1 ever"],correct:1,explanation:"NEC 501.15(A) \u2014 sealed fitting dentro de 18 inches del explosion-proof enclosure que contenga arcs/sparks/high-temp. Tambi\xE9n boundary seal al salir de zona clasificada. El sello previene propagaci\xF3n de llama por el conduit.",reference:"NEC 501.15"},{category:"Hazardous Locations",difficulty:"hard",q:"Comercial spray booth de pintura \u2014 \xBFqu\xE9 classification aplica al interior de la booth durante operaci\xF3n?",options:["Unclassified para el interior booth spr","Class I Div 1 interior + Div 2 openings","Class II Div 1 para booth spray paint","Class III Div 2 para booth spray paint"],correct:1,explanation:"NEC 516.3(C) \u2014 interior de spray booth = Class I Div 1 durante spraying. \xC1rea within 3 ft de openings = Class I Div 2. Por eso lighting debe ser explosion-proof o sealed lenses outside view panels. Todas las instalaciones sujetas a fire marshal approval.",reference:"NEC 516.3"},{category:"Solar PV NEC 690",difficulty:"easy",q:"California Title 24 2020+ exige sistemas solar PV en:",options:["Solo edificios comerciales nuevos Title","Nuevas viviendas single/multi hasta 3p","Solo casas sobre 2,000 sq ft Title 24","Opcional sin mandate en Title 24 rule"],correct:1,explanation:"Title 24 Part 6 (2020 actualizado en 2023) mandates solar PV en nuevas viviendas unifamiliares y multi-family hasta 3 pisos en California. Sizing basado en electricity demand del edificio. Contratistas C-10 tambi\xE9n instalan C-46 (solar).",reference:"CA Title 24 Part 6, CEC"},{category:"Solar PV NEC 690",difficulty:"medium",q:"NEC 690.12 Rapid Shutdown \u2014 \xBFqu\xE9 voltage debe alcanzar un PV array dentro de 30 segundos de activation?",options:["0V dentro de 30 segundos todo array ok","30V inside boundary, 80V outside array","50V siempre dentro de 30 seg todo PV","120V dentro de 30 seg todo el array PV"],correct:1,explanation:"NEC 690.12(B)(2) 2023 \u2014 rapid shutdown: dentro del array boundary 80V, outside array boundary 30V (dentro de 1 ft), ambos dentro de 30 segundos. Protege firefighters de energized DC conductors on roof. Requiere module-level shutdown devices.",reference:"NEC 690.12(B)(2)"},{category:"Solar PV NEC 690",difficulty:"medium",q:"PV module nameplate: Voc=40V, Isc=10A. Para calcular circuit ampacity, \xBFqu\xE9 factor se aplica a Isc seg\xFAn NEC 690.8?",options:["100% Isc sin aplicar factor continuous","125% Isc solo un factor continuous only","156% Isc (125% \xD7 125%) irradiance/cont","200% Isc aplicando factor doble error"],correct:2,explanation:"NEC 690.8(A)(1) \u2014 continuous PV current = Isc \xD7 1.25 (irradiance factor). Luego 690.8(B) aplica otro 125% para conductor sizing continuous load = 156% total. 10A \xD7 1.56 = 15.6A ampacidad m\xEDnima conductor.",reference:"NEC 690.8"},{category:"Solar PV NEC 690",difficulty:"hard",q:"NEC 690.13 PV DC disconnect \u2014 \xBFqu\xE9 rating debe tener?",options:["AC only rating switch PV DC disconnect","DC rated apropiado Voc/Isc accessible","500V AC m\xEDnimo switch PV DC disconnect","Standard AC breaker sirve para PV DC"],correct:1,explanation:"NEC 690.13 \u2014 PV system DC disconnect debe ser DC-rated (switches AC no interrumpen DC adecuadamente \u2014 el arc es sostenido). Debe manejar PV Voc max (con cold temp correction 690.7) y Isc calculada. Readily accessible para firefighters.",reference:"NEC 690.13, 690.15"},{category:"Title 24 California",difficulty:"easy",q:"Title 24 California requiere qu\xE9 tipo de lighting control en \xE1reas residenciales seg\xFAn \xA7150.0(k)?",options:["Solo switches regulares sin control need","High efficacy LED dimmer/vacancy sensor","Solo incandescent bulbs permitidos Title","Sin requirements lighting control Title"],correct:1,explanation:"Title 24 \xA7150.0(k) \u2014 high-efficacy lighting (LED JA8 compliant) en todas las \xE1reas permanentes. Bathrooms, garages, laundry requieren vacancy sensors. Hallways con manual-ON + auto-OFF. El inspector C-10 debe conocer estos requirements.",reference:"CA Title 24 \xA7150.0(k)"},{category:"Title 24 California",difficulty:"medium",q:"Title 24 exige EV charging readiness en nuevos homes. \xBFQu\xE9 debe proveerse como m\xEDnimo?",options:["Nothing, es opcional el Title 24 EV req","Circuito 40A 208/240V ready EV future","Solo un outlet 120V standard garage EV","Charger instalado completo Level 2 full"],correct:1,explanation:"Title 24 \xA7150.0(o) \u2014 EV readiness: raceway desde panel a garage, panel space reservado, y typical 40-50A circuit capability para futuro Level 2. Multi-family requiere 10% de spaces EV-ready + adicional EV-capable. Contractor C-10 documenta esto.",reference:"CA Title 24 \xA7150.0(o)"},{category:"Title 24 California",difficulty:"medium",q:"T\xEDtulo 24 commercial lighting \u2014 el Lighting Power Density (LPD) para office space es aproximadamente:",options:["2.0 W/sq ft LPD office Title 24 2022","0.65 W/sq ft LPD office Title 24 2022","1.5 W/sq ft LPD office Title 24 2022","Sin l\xEDmite LPD office Title 24 2022 ok"],correct:1,explanation:"Title 24 2022 Table 140.6-A \u2014 office space LPD ~0.65 W/sq ft (reducido cada ciclo por LED efficiency). Complementado con occupancy sensors, daylighting controls. Mucho m\xE1s restrictivo que ASHRAE 90.1 nacional. Auditor\xEDa de energy en cada permit.",reference:"CA Title 24 Table 140.6-A"},{category:"Working Clearances NEC 110",difficulty:"easy",q:"Seg\xFAn NEC 110.26(A)(2), el width del working space frente a un electrical panel es m\xEDnimo:",options:["18 inches width working space m\xEDnimo","24 inches width working space m\xEDnimo","30 inches o ancho equipo (el mayor)","36 inches width working space m\xEDnimo"],correct:2,explanation:"NEC 110.26(A)(2) \u2014 width del working space = 30 inches m\xEDnimo o el ancho del equipo, lo que sea mayor. No necesita estar centrado frente al panel, pero el panel debe abrir 90\xB0+ dentro del espacio.",reference:"NEC 110.26(A)(2)"},{category:"Working Clearances NEC 110",difficulty:"medium",q:"NEC 110.21(B) \u2014 Arc flash warning label debe incluir como m\xEDnimo:",options:["Solo 'DANGER' label sin m\xE1s info text","Voltage, arc flash boundary, PPE/energy","Nombre del contratista que instal\xF3 eq","Solo fecha de instalaci\xF3n equipment"],correct:1,explanation:"NEC 110.16 + 110.21(B) + NFPA 70E \u2014 labels en equipment likely to require examination while energized deben mostrar: nominal system voltage, arc flash boundary, at least one de: available incident energy con corresponding distance, minimum arc rating de PPE, site-specific PPE level, o Hazard/Risk category.",reference:"NEC 110.16, 110.21(B)"},{category:"Working Clearances NEC 110",difficulty:"medium",q:"Dedicated equipment space NEC 110.26(E) \u2014 el espacio above del panel es zona dedicada de qu\xE9 altura?",options:["6 inches above panel dedicated space","12 inches above panel dedicated space","6 feet above equipment or ceiling low","Ilimitado above panel dedicated space"],correct:2,explanation:"NEC 110.26(E)(1) \u2014 dedicated space = \xE1rea directamente above el panel, desde floor hasta 6 ft arriba del equipo OR structural ceiling (lo que sea menor). Prohibido piping, ducts, foreign systems en esta zona (excepto sprinkler protection permitida).",reference:"NEC 110.26(E)(1)"},{category:"Working Clearances NEC 110",difficulty:"hard",q:"Panel de 480V trif\xE1sico con 800A \u2014 sobre el lado opuesto hay una pared concreta grounded. \xBFCu\xE1l es el working space depth seg\xFAn Table 110.26(A)(1) (Condici\xF3n 2)?",options:["3 feet working depth Condition 2 ampl","3.5 feet working depth Condition 2 480","4 feet working depth Condition 2 ampl","5 feet working depth Condition 2 ampl"],correct:1,explanation:"Table 110.26(A)(1) \u2014 para 151-600V con grounded surface al opposite (Condition 2), working depth = 3.5 ft (1.07m). Condition 1 (nada grounded) = 3 ft; Condition 3 (partes vivas opposite) = 4 ft. 480V entra al rango 151-600V.",reference:"NEC Table 110.26(A)(1)"}];
